 86→/// Handle for interacting with Courier
 87→///
 88→/// Provides async methods for P2P operations.
 89→/// Uses `IrohConnection` (production) type internally.
 90→#[derive(Clone)]
 91→pub struct CourierHandle {
 92→    coordinator: ActorRef<IrohCoordinatorMessage>,
 93→}
 94→
 95→impl CourierHandle {
 96→    /// Create a new CourierHandle
 97→    pub fn new(coordinator: ActorRef<IrohCoordinatorMessage>) -> Self {
 98→        Self { coordinator }
 99→    }
100→
101→    /// Connect to a node (fire-and-forget)
102→    ///
103→    /// **Flow**:
104→    /// 1. Coordinator stores permit and marks as pending
105→    /// 2. CourierRunner connects via transport
106→    /// 3. on_connected spawns PeerActor with permit (auto-initiates handshake)
107→    /// 4. App receives PeerAuthenticated or ConnectionFailed event via event channel
108→    ///
109→    /// **Events**:
110→    /// - `CourierEvent::PeerAuthenticated` on success
111→    /// - `CourierEvent::ConnectionFailed` on failure
112→    pub fn connect(&self, node_id: &str, permit: &str) -> Result<(), String> {
113→        let node_id: NodeId = node_id
114→            .parse()
115→            .map_err(|e| format!("Invalid node_id: {}", e))?;
116→
117→        self.coordinator
118→            .cast(IrohCoordinatorMessage::Connect {
119→                node_id,
120→                permit: permit.to_string(),
121→            })
122→            .map_err(|e| format!("Failed to send Connect: {:?}", e))
123→    }
124→
125→    /// Get PeerActor ref for direct communication
126→    async fn get_peer_actor(&self, node_id: NodeId) -> Result<ActorRef<PeerMessage>, String> {
127→        let (tx, rx) = oneshot::channel();
128→
129→        self.coordinator
130→            .cast(IrohCoordinatorMessage::GetPeerActor { node_id, response: tx })
131→            .map_err(|e| format!("Failed to send GetPeerActor: {:?}", e))?;
132→
133→        rx.await
134→            .map_err(|_| "GetPeerActor channel closed".to_string())?
135→            .ok_or_else(|| format!("No PeerActor for node {}", node_id))
136→    }
137→
138→    /// Publish a space to a node (sends directly to PeerActor)
139→    pub async fn publish_space(&self, space_id: &str, node_id: &str) -> Result<(), String> {
140→        let node_id: NodeId = node_id
141→            .parse()
142→            .map_err(|e| format!("Invalid node_id: {}", e))?;
143→
144→        let peer_actor = self.get_peer_actor(node_id).await?;
145→        peer_actor
146→            .cast(PeerMessage::PublishSpace { space_id: space_id.to_string() })
147→            .map_err(|e| format!("Failed to send PublishSpace: {:?}", e))?;
148→
149→        Ok(())
150→    }
151→
152→    /// Get shareable link for a space (sends request to PeerActor, awaits response)
153→    ///
154→    /// **Flow**: Sends GetShareableLinkRequest to node, waits for GetShareableLinkResponse
155→    pub async fn get_shareable_link(&self, space_id: &str, node_id: &str) -> Result<String, String> {
156→        let node_id: NodeId = node_id
157→            .parse()
158→            .map_err(|e| format!("Invalid node_id: {}", e))?;
159→
160→        let peer_actor = self.get_peer_actor(node_id).await?;
161→
162→        // Create callback channel
163→        let (response_tx, response_rx) = tokio::sync::oneshot::channel();
164→
165→        peer_actor
166→            .cast(PeerMessage::GetShareableLink {
167→                space_id: space_id.to_string(),
168→                response_tx,
169→            })
170→            .map_err(|e| format!("Failed to send GetShareableLink: {:?}", e))?;
171→
172→        // Wait for the response
173→        response_rx
174→            .await
175→            .map_err(|_| "Response channel closed".to_string())?
176→    }
177→
178→    /// Request space as viewer (sends directly to PeerActor)
179→    pub async fn request_space_as_viewer(
180→        &self,
181→        space_id: &str,
182→        node_id: &str,
183→        viewer_permit: &str,
184→    ) -> Result<(), String> {
185→        let node_id: NodeId = node_id
186→            .parse()
187→            .map_err(|e| format!("Invalid node_id: {}", e))?;
188→
189→        let peer_actor = self.get_peer_actor(node_id).await?;
190→        peer_actor
191→            .cast(PeerMessage::RequestSpace {
192→                space_id: space_id.to_string(),
193→                viewer_permit: viewer_permit.to_string(),
194→            })
195→            .map_err(|e| format!("Failed to send RequestSpace: {:?}", e))?;
196→
197→        Ok(())
198→    }
199→
200→    /// Get a reference to the coordinator (for tests)
201→    pub fn coordinator(&self) -> &ActorRef<IrohCoordinatorMessage> {
202→        &self.coordinator
203→    }
204→
205→    /// Ensure sync with a user (forward SyncEvent::EnsureSync to Coordinator)
206→    ///
207→    /// **Context**: Scribe emitted EnsureSync - forward to Coordinator
208→    /// **Coordinator will**: Resolve user_did → device, connect if needed, PeerActor subscribes
209→    pub fn ensure_sync(&self, user_did: &str) -> Result<(), String> {
210→        self.coordinator
211→            .cast(IrohCoordinatorMessage::EnsureSync {
212→                user_did: user_did.to_string(),
213→            })
214→            .map_err(|e| format!("Failed to send EnsureSync: {:?}", e))
215→    }
216→
217→    /// Broadcast datagram to all authenticated peers
218→    ///
219→    /// **Context**: Send ephemeral data (cursor, typing) to all connected users
220→    /// **Coordinator will**: Send datagram to each authenticated peer's connection
221→    pub fn broadcast_datagram(&self, data: Vec<u8>) -> Result<(), String> {
222→        self.coordinator
223→            .cast(IrohCoordinatorMessage::BroadcastDatagram { data })
224→            .map_err(|e| format!("Failed to broadcast datagram: {:?}", e))
225→    }
226→
227→    /// Notify that a page was opened - refreshes subscriptions
228→    ///
229→    /// **Context**: App opened a page, ensures sync subscriptions are established
230→    /// **Coordinator will**: Send RefreshSubscriptions to all authenticated PeerActors
231→    /// **Use case**: Fixes race condition where page opens after connection established
232→    pub fn page_opened(&self, page_id: &str) -> Result<(), String> {
233→        self.coordinator
234→            .cast(IrohCoordinatorMessage::PageOpened {
235→                page_id: page_id.to_string(),
236→            })
237→            .map_err(|e| format!("Failed to notify page opened: {:?}", e))
238→    }
239→
240→    /// Distribute layer permits for a new dynamic layer (forward to Coordinator)
241→    ///
242→    /// **Context**: Scribe emitted NewDynamicLayer — forward to Coordinator for distribution
243→    /// **Coordinator will**: Store permits in butler, send LayerPermitMsg to connected peers
244→    pub fn distribute_layer_permits(
245→        &self,
246→        page_id: &str,
247→        layer_name: &str,
248→        permits: Vec<(String, String)>,
249→    ) -> Result<(), String> {
250→        self.coordinator
251→            .cast(IrohCoordinatorMessage::DistributeLayerPermits {
252→                page_id: page_id.to_string(),
253→                layer_name: layer_name.to_string(),
254→                permits,
255→            })
256→            .map_err(|e| format!("Failed to send DistributeLayerPermits: {:?}", e))
257→    }
258→
259→    /// Distribute updated page permits to peers (forward to Coordinator)
260→    ///
261→    /// **Context**: Page permits reissued with new app layers — forward to Coordinator
262→    /// **Coordinator will**: Store permits in butler, send PermitUpdate to connected peers
263→    pub fn distribute_page_permit_updates(
264→        &self,
265→        page_id: &str,
266→        permits: Vec<(String, String)>,
267→    ) -> Result<(), String> {
268→        self.coordinator
269→            .cast(IrohCoordinatorMessage::DistributePagePermitUpdates {
270→                page_id: page_id.to_string(),
271→                permits,
272→            })
273→            .map_err(|e| format!("Failed to send DistributePagePermitUpdates: {:?}", e))
274→    }
275→
276→    /// Check if a node is authenticated (handshake complete)
277→    ///
278→    /// **Context**: Script/app wants to wait for auth before publishing
279→    /// **Returns**: true if handshake complete with this node
280→    pub async fn is_node_authenticated(&self, node_id: &str) -> Result<bool, String> {
281→        let node_id: NodeId = node_id
282→            .parse()
283→            .map_err(|e| format!("Invalid node_id: {}", e))?;
284→
285→        let (tx, rx) = oneshot::channel();
286→        self.coordinator
287→            .cast(IrohCoordinatorMessage::IsNodeAuthenticated {
288→                node_id,
289→                response: tx,
290→            })
291→            .map_err(|e| format!("Failed to send IsNodeAuthenticated: {:?}", e))?;
292→
293→        rx.await.map_err(|_| "Channel closed".to_string())
294→    }
295→}
