297→/// Handshake services - wraps Butler for handshake operations
298→///
299→/// In the actor architecture, Butler is passed directly to the Coordinator.
300→/// This type exists for API compatibility.
301→pub struct HandshakeServices {
302→    pub butler: Arc<Butler>,
303→}
304→
305→impl HandshakeServices {
306→    pub fn new(butler: Arc<Butler>) -> Self {
307→        Self { butler }
308→    }
309→}
310→
311→/// Courier initialization helper
312→///
313→/// Provides a simpler initialization API that matches for Courier consumers.
314→pub struct Courier;
315→
316→impl Courier {
317→    /// Initialize Courier with services
318→    ///
319→    /// Returns a handle, event receiver, and the runner that must be spawned.
320→    pub fn init_with_services(
321→        mode: CourierMode,
322→        transport: Arc<Transport>,
323→        services: Option<Arc<HandshakeServices>>,
324→    ) -> (CourierHandle, mpsc::Receiver<CourierEvent>, CourierRunner) {
325→        let butler = services
326→            .map(|s| s.butler.clone())
327→            .expect("HandshakeServices required");
328→
329→        let (event_tx, event_rx) = mpsc::channel(100);
330→        let (connect_tx, connect_rx) = mpsc::channel(16);
331→
332→        let mut runner = CourierRunner {
333→            mode,
334→            transport: transport.clone(),
335→            butler,
336→            event_tx,
337→            connect_rx,
338→            coordinator: None,
339→        };
340→
341→        // Spawn coordinator and store in runner so run() uses the same actor
342→        let coordinator = runner.spawn_coordinator_sync(connect_tx);
343→        runner.coordinator = Some(coordinator.clone());
344→
345→        let handle = CourierHandle::new(coordinator);
346→
347→        (handle, event_rx, runner)
348→    }
349→}
350→
351→/// Runner that must be spawned to process events
352→pub struct CourierRunner {
353→    mode: CourierMode,
354→    transport: Arc<Transport>,
355→    butler: Arc<Butler>,
356→    event_tx: mpsc::Sender<CourierEvent>,
357→    connect_rx: mpsc::Receiver<crate::coordinator::ConnectRequest>,
358→    coordinator: Option<ActorRef<IrohCoordinatorMessage>>,
359→}
360→
361→impl CourierRunner {
362→    /// Convert TransportEvent to IrohCoordinatorMessage
363→    ///
364→    /// Maps the concrete TransportEvent (with ConnectionHandle) to the generic
365→    /// CoordinatorMessage<IrohConnection> by wrapping the handle.
366→    fn from_transport_event(event: TransportEvent) -> Option<IrohCoordinatorMessage> {
367→        match event {
368→            TransportEvent::Connected { node_id, conn } => {
369→                Some(IrohCoordinatorMessage::Connected {
370→                    node_id,
371→                    conn: conn.into(), // ConnectionHandle -> IrohConnection
372→                })
373→            }
374→            TransportEvent::Disconnected { node_id } => {
375→                Some(IrohCoordinatorMessage::Disconnected { node_id })
376→            }
377→        }
378→    }
379→
380→    /// Spawn coordinator synchronously and return its ActorRef
381→    ///
382→    /// Uses block_in_place to spawn the actor synchronously so we can
383→    /// return the handle immediately from init_with_services.
384→    fn spawn_coordinator_sync(
385→        &self,
386→        connect_tx: mpsc::Sender<crate::coordinator::ConnectRequest>,
387→    ) -> ActorRef<IrohCoordinatorMessage> {
388→        let node_id = self.transport.node_id();
389→        let butler = self.butler.clone();
390→        let transport = self.transport.clone();
391→        let mode = self.mode;
392→        let event_tx = self.event_tx.clone();
393→
394→        tokio::task::block_in_place(|| {
395→            tokio::runtime::Handle::current().block_on(async {
396→                let coordinator = IrohCoordinator::new();
397→                let blob_store = crate::peer_actor::BlobStore::Real(transport);
398→                let (actor_ref, _) = Actor::spawn(
399→                    Some("coordinator".to_string()),
400→                    coordinator,
401→                    (node_id, mode, butler.clone(), blob_store, Some(connect_tx), Some(event_tx), None),
402→                )
403→                .await
404→                .expect("Failed to spawn Coordinator");
405→
406→                actor_ref
407→            })
408→        })
409→    }
410→
411→    /// Run the courier event loop
412→    ///
413→    /// Processes transport events and connection requests, forwarding to Coordinator.
414→    /// The Coordinator must have been spawned during init_with_services.
415→    pub async fn run(mut self, mut transport_rx: mpsc::Receiver<TransportEvent>) {
416→        // Use the coordinator that was spawned during init
417→        let coordinator = self
418→            .coordinator
419→            .take()
420→            .expect("Coordinator must be spawned during init_with_services");
421→
422→        info!("Courier runner started");
423→
424→        loop {
425→            tokio::select! {
426→                // Handle transport events
427→                Some(event) = transport_rx.recv() => {
428→                    if let Some(msg) = Self::from_transport_event(event) {
429→                        if let Err(e) = coordinator.cast(msg) {
430→                            error!("Failed to send message to coordinator: {:?}", e);
431→                        }
432→                    }
433→                }
434→
435→                // Handle connection requests from Coordinator (e.g., EnsureSync)
436→                // Note: Coordinator already stored permit in pending_permits before sending this request
437→                Some(req) = self.connect_rx.recv() => {
438→                    info!(node_id = %req.node_id, "Processing connection request");
439→
440→                    // Connect via transport - on_connected will use stored permit
441→                    // Transport::connect now includes retry with exponential backoff
442→                    let transport = self.transport.clone();
443→                    let node_id = req.node_id;
444→                    let event_tx = self.event_tx.clone();
445→                    tokio::spawn(async move {
446→                        match transport.connect(node_id).await {
447→                            Ok(_handle) => {
448→                                info!(node_id = %node_id, "Auto-connect successful for sync");
449→                                // TransportEvent::Connected will be emitted by transport,
450→                                // which triggers PeerActor spawn and handshake
451→                            }
452→                            Err(e) => {
453→                                warn!(node_id = %node_id, error = %e, "Auto-connect failed for sync (after retries)");
454→                                // Notify app that connection failed
455→                                let _ = event_tx.send(CourierEvent::ConnectionFailed {
456→                                    node_id: node_id.to_string(),
457→                                    error: e.to_string(),
458→                                }).await;
459→                            }
460→                        }
461→                    });
462→                }
463→
464→                // Both channels closed - exit
465→                else => break,
466→            }
467→        }
468→
469→        // Shutdown coordinator
470→        let _ = coordinator.cast(IrohCoordinatorMessage::Shutdown);
471→        info!("Courier runner stopped");
472→    }
473→}
