156→impl<C: Connection> Coordinator<C> {
157→    pub fn new() -> Self {
158→        Self { _phantom: PhantomData }
159→    }
160→
161→    /// Emit an event to the app layer via event_tx channel
162→    fn emit_event(state: &CoordinatorState<C>, event: CourierEvent) {
163→        if let Some(tx) = &state.event_tx {
164→            if let Err(e) = tx.try_send(event) {
165→                warn!("Failed to emit event: {}", e);
166→            }
167→        }
168→    }
169→
170→    /// Process a ConnectionEvent and convert to CoordinatorMessage
171→    ///
172→    /// **Note**: Transport now only emits lifecycle events (Connected/Disconnected).
173→    /// Message reading is done by PeerSession directly from the Connection.
174→    pub fn from_connection_event(event: transport::ConnectionEvent<C>) -> Option<CoordinatorMessage<C>> {
175→        match event {
176→            transport::ConnectionEvent::Connected { node_id, conn } => {
177→                Some(CoordinatorMessage::Connected { node_id, conn })
178→            }
179→            transport::ConnectionEvent::Disconnected { node_id } => {
180→                Some(CoordinatorMessage::Disconnected { node_id })
181→            }
182→        }
183→    }
184→}
185→
186→impl<C: Connection> Default for Coordinator<C> {
187→    fn default() -> Self {
188→        Self::new()
189→    }
190→}
191→
192→impl<C: Connection> Actor for Coordinator<C> {
193→    type Msg = CoordinatorMessage<C>;
194→    type State = CoordinatorState<C>;
195→    type Arguments = (
196→        NodeId,
197→        CourierMode,
198→        Arc<Butler>,
199→        crate::peer_actor::BlobStore,
200→        Option<mpsc::Sender<ConnectRequest>>,
201→        Option<mpsc::Sender<CourierEvent>>,
202→        Option<mpsc::UnboundedSender<MessageTrace>>,
203→    );
204→
205→    #[instrument(skip_all)]
206→    async fn pre_start(
207→        &self,
208→        _myself: ActorRef<Self::Msg>,
209→        args: Self::Arguments,
210→    ) -> Result<Self::State, ActorProcessingErr> {
211→        let (our_node_id, mode, butler, blob_store, connect_tx, event_tx, message_tx) = args;
212→
213→        info!("Coordinator started in {:?} mode (node_id={})", mode, our_node_id);
214→
215→        Ok(CoordinatorState::new(
216→            our_node_id,
217→            mode,
218→            butler,
219→            blob_store,
220→            connect_tx,
221→            event_tx,
222→            message_tx,
223→        ))
224→    }
225→
226→    async fn handle(
227→        &self,
228→        myself: ActorRef<Self::Msg>,
229→        message: Self::Msg,
230→        state: &mut Self::State,
231→    ) -> Result<(), ActorProcessingErr> {
232→        match message {
233→
234→            CoordinatorMessage::Connected { node_id, conn } => {
235→                self.on_connected(myself.clone(), node_id, conn, state).await;
236→            }
237→
238→            CoordinatorMessage::Disconnected { node_id } => {
239→                self.on_disconnected(node_id, state).await;
240→            }
241→
242→            CoordinatorMessage::PeerAuthenticated {
243→                node_id,
244→                peer_type,
245→                did,
246→                username,
247→            } => {
248→                info!("Peer authenticated: {} ({}) - {:?}", username, node_id, peer_type);
249→                state.authenticate_peer(node_id, peer_type, did.clone(), username.clone());
250→
251→                // Mark sovereign node as connected (for User mode connecting to their Node)
252→                if peer_type == PeerType::MyNode {
253→                    let node_id_str = node_id.to_string();
254→                    match state.butler.nodes().set_connected(&node_id_str, true) {
255→                        Ok(true) => info!("Marked sovereign node {} as connected", node_id_str),
256→                        Ok(false) => debug!("Sovereign node {} not found in storage", node_id_str),
257→                        Err(e) => warn!("Failed to mark sovereign node connected: {}", e),
258→                    }
259→                }
260→
261→                // Emit event for app layer
262→                Self::emit_event(state, CourierEvent::PeerAuthenticated {
263→                    node_id: node_id.to_string(),
264→                    did,
265→                    username,
266→                });
267→            }
268→
269→            CoordinatorMessage::PeerFailed { node_id, reason } => {
270→                warn!("Peer failed: {} - {}", node_id, reason);
271→
272→                // Emit failure event for app layer
273→                Self::emit_event(state, CourierEvent::ConnectionFailed {
274→                    node_id: node_id.to_string(),
275→                    error: reason,
276→                });
277→
278→                state.remove_peer(node_id);
279→            }
280→
281→            CoordinatorMessage::Connect { node_id, permit } => {
282→                self.on_connect(node_id, permit, state).await;
283→            }
284→
285→            CoordinatorMessage::GetPeerActor { node_id, response } => {
286→                let actor = state.get_actor(&node_id).cloned();
287→                let _ = response.send(actor);
288→            }
289→
290→            CoordinatorMessage::RelayDatagram { from_node_id, data } => {
291→                if state.mode == CourierMode::Node {
292→                    for (peer_node_id, entry) in state.authenticated_peers() {
293→                        if peer_node_id != from_node_id {
294→                            if let Err(e) = entry.conn.send_datagram(&data) {
295→                                debug!(from = %from_node_id, to = %peer_node_id, error = %e, "Failed to relay datagram");
296→                            }
297→                        }
298→                    }
299→                }
300→            }
301→
302→            CoordinatorMessage::BroadcastDatagram { data } => {
303→                for (node_id, entry) in state.authenticated_peers() {
304→                    if let Err(e) = entry.conn.send_datagram(&data) {
305→                        debug!(node_id = %node_id, error = %e, "Failed to send datagram");
306→                    }
307→                }
308→            }
309→
310→            CoordinatorMessage::EnsureSync { user_did } => {
311→                self.on_ensure_sync(myself.clone(), user_did, state).await;
312→            }
313→
314→            CoordinatorMessage::DistributeLayerPermits { page_id, layer_name, permits } => {
315→                self.on_distribute_layer_permits(&page_id, &layer_name, &permits, state).await;
316→            }
317→
318→            CoordinatorMessage::DistributePagePermitUpdates { page_id, permits } => {
319→                self.on_distribute_page_permit_updates(&page_id, &permits, state).await;
320→            }
321→
322→            CoordinatorMessage::PageOpened { page_id } => {
323→                self.on_page_opened(&page_id, state).await;
324→            }
325→
326→            CoordinatorMessage::IsNodeAuthenticated { node_id, response } => {
327→                let is_auth = state.is_authenticated(&node_id);
328→                let _ = response.send(is_auth);
329→            }
330→
331→            CoordinatorMessage::Shutdown => {
332→                info!("Coordinator shutting down");
333→                for (node_id, entry) in state.peers.drain() {
334→                    debug!("Stopping PeerActor {}", node_id);
335→                    entry.actor.stop(Some("coordinator shutdown".to_string()));
336→                }
337→                myself.stop(Some("shutdown".to_string()));
338→            }
339→        }
340→
341→        Ok(())
342→    }
343→
344→    async fn handle_supervisor_evt(
345→        &self,
346→        _myself: ActorRef<Self::Msg>,
347→        event: SupervisionEvent,
348→        state: &mut Self::State,
349→    ) -> Result<(), ActorProcessingErr> {
350→        match event {
351→            SupervisionEvent::ActorStarted(cell) => {
352→                debug!("Child actor started: {:?}", cell.get_id());
353→            }
354→            SupervisionEvent::ActorTerminated(cell, _, reason) => {
355→                debug!(
356→                    "Child actor {} terminated: {:?}",
357→                    cell.get_id(),
358→                    reason
359→                );
360→                // Find and remove from unified registry
361→                state.peers.retain(|node_id, entry| {
362→                    if entry.actor.get_id() == cell.get_id() {
363→                        debug!("Removing terminated PeerActor {}", node_id);
364→                        false
365→                    } else {
366→                        true
367→                    }
368→                });
369→            }
370→            SupervisionEvent::ActorFailed(cell, error) => {
371→                error!("Child actor {} failed: {}", cell.get_id(), error);
372→                // Same cleanup as terminated
373→                state.peers.retain(|node_id, entry| {
374→                    if entry.actor.get_id() == cell.get_id() {
375→                        debug!("Removing failed PeerActor {}", node_id);
376→                        false
377→                    } else {
378→                        true
379→                    }
380→                });
381→            }
382→            _ => {}
383→        }
384→
385→        Ok(())
386→    }
387→}
388→
389→impl<C: Connection> Coordinator<C> {
390→    /// Handle new connection - spawn PeerActor with permit if outbound
391→    #[instrument(skip_all, fields(node_id = %node_id))]
392→    async fn on_connected(
393→        &self,
394→        myself: ActorRef<CoordinatorMessage<C>>,
395→        node_id: NodeId,
396→        conn: C,
397→        state: &mut CoordinatorState<C>,
398→    ) {
399→        info!("New connection from: {}", node_id);
400→
401→        // Check if this was an outbound connection WE initiated - get permit if so
402→        let is_outbound = state.pending_connections.remove(&node_id);
403→        let permit = if is_outbound {
404→            state.pending_permits.remove(&node_id)
405→        } else {
406→            None
407→        };
408→
409→        if is_outbound && permit.is_none() {
410→            warn!("Outbound connection to {} but no permit - cannot handshake", node_id);
411→        }
412→
413→        // Spawn PeerActor - if permit provided, it auto-initiates handshake
414→        let peer_actor = PeerActor::<C>::new(node_id);
415→        let args = PeerActorArgs {
416→            mode: state.mode,
417→            conn: conn.clone(),
418→            coordinator: myself.clone(),
419→            butler: state.butler.clone(),
420→            blob_store: state.blob_store.clone(),
421→            permit,
422→            message_tx: state.message_tx.clone(),
423→            our_node_id: state.our_node_id,
424→        };
425→
426→        match Actor::spawn_linked(None, peer_actor, args, myself.get_cell()).await {
427→            Ok((actor_ref, _)) => {
428→                state.add_peer(node_id, actor_ref, conn);
429→                debug!("PeerActor spawned for {}", node_id);
430→            }
431→            Err(e) => {
432→                error!("Failed to spawn PeerActor for {}: {:?}", node_id, e);
433→            }
434→        }
435→    }
436→
437→    /// Handle disconnection - cleanup peer state and emit event
438→    #[instrument(skip_all, fields(node_id = %node_id))]
439→    async fn on_disconnected(&self, node_id: NodeId, state: &mut CoordinatorState<C>) {
440→        info!("Disconnected: {}", node_id);
441→
442→        if let Some(entry) = state.peers.remove(&node_id) {
443→            entry.actor.stop(Some("disconnected".to_string()));
444→        }
445→
446→        state.pending_connections.remove(&node_id);
447→        state.pending_permits.remove(&node_id);
448→
449→        // Emit disconnect event for app layer
450→        Self::emit_event(state, CourierEvent::PeerDisconnected {
451→            node_id: node_id.to_string(),
452→        });
453→    }
454→
455→    /// Connect to peer (fire-and-forget, result via events)
456→    ///
457→    /// **Context**: App calls connect(), we store permit and mark as pending
458→    /// **Transport**: CourierRunner sees pending_connections and calls transport.connect()
459→    /// **Events**: PeerAuthenticated on success, ConnectionFailed on failure
460→    #[instrument(skip_all, fields(node_id = %node_id))]
461→    async fn on_connect(
462→        &self,
463→        node_id: NodeId,
464→        permit: String,
465→        state: &mut CoordinatorState<C>,
466→    ) {
467→        info!("Connect: node={}", node_id);
468→
469→        // Check if already authenticated - emit event immediately
470→        if state.is_authenticated(&node_id) {
471→            info!("Peer {} already authenticated", node_id);
472→            if let Some(auth) = state.get_auth(&node_id) {
473→                Self::emit_event(state, CourierEvent::PeerAuthenticated {
474→                    node_id: node_id.to_string(),
475→                    did: auth.did.clone(),
476→                    username: auth.username.clone(),
477→                });
478→            }
479→            return;
480→        }
481→
482→        // Check if already connected - initiate handshake with existing PeerActor
483→        if let Some(actor) = state.get_actor(&node_id).cloned() {
484→            info!("Peer {} already connected - initiating handshake", node_id);
485→            if let Err(e) = actor.cast(PeerMessage::InitiateHandshake { permit }) {
486→                warn!("Failed to send InitiateHandshake to {}: {:?}", node_id, e);
487→            }
488→            return;
489→        }
490→
491→        // Mark as pending outbound connection and store permit
492→        state.pending_connections.insert(node_id);
493→        state.pending_permits.insert(node_id, permit.clone());
494→
495→        // Request transport connection via CourierRunner
496→        if let Some(ref tx) = state.connect_tx {
497→            if let Err(e) = tx.try_send(ConnectRequest { node_id, permit }) {
498→                warn!(node_id = %node_id, error = %e, "Failed to send connect request");
499→                Self::emit_event(state, CourierEvent::ConnectionFailed {
500→                    node_id: node_id.to_string(),
501→                    error: format!("Failed to initiate connection: {}", e),
502→                });
503→            }
504→        }
505→    }
506→
507→    /// Handle EnsureSync from Scribe - connect to user if not already connected
508→    #[instrument(skip_all, fields(user_did = %user_did))]
509→    async fn on_ensure_sync(
510→        &self,
511→        _myself: ActorRef<CoordinatorMessage<C>>,
512→        user_did: String,
513→        state: &mut CoordinatorState<C>,
514→    ) {
515→        info!(user_did = %user_did, "Scribe requested sync with user");
516→
517→        // Check if user is already connected
518→        if let Some(peer_actor) = self.get_peer_actor_for_user(&user_did, state) {
519→            info!(user_did = %user_did, "User already connected, sending RefreshSubscriptions to PeerActor");
520→            let _ = peer_actor.cast(PeerMessage::RefreshSubscriptions);
521→            return;
522→        }
523→
524→        // Resolve user_did to device info
525→        let device_info = match state.butler.contacts().resolve_device(&user_did) {
526→            Ok(Some(info)) => info,
527→            Ok(None) => {
528→                // In Node mode, viewers initiate connections - we don't reconnect to them
529→                // This is expected behavior, not a warning condition
530→                if state.mode == CourierMode::Node {
531→                    debug!(user_did = %user_did, "Viewer not connected (will reconnect when online)");
532→                } else {
533→                    warn!(user_did = %user_did, "No device info found for user");
534→                }
535→                return;
536→            }
537→            Err(e) => {
538→                warn!(user_did = %user_did, error = %e, "Failed to resolve device");
539→                return;
540→            }
541→        };
542→
543→        let node_id = match device_info.node_id.parse::<NodeId>() {
544→            Ok(id) => id,
545→            Err(e) => {
546→                warn!(node_id = %device_info.node_id, error = ?e, "Failed to parse node_id");
547→                return;
548→            }
549→        };
550→
551→        // Check if already connecting/connected
552→        if state.is_connected(&node_id) || state.pending_connections.contains(&node_id) {
553→            debug!(user_did = %user_did, node_id = %node_id, "Already connected/connecting");
554→            return;
555→        }
556→
557→        info!(user_did = %user_did, node_id = %node_id, "Requesting connection for sync");
558→
559→        state.pending_connections.insert(node_id);
560→        state.pending_permits.insert(node_id, device_info.permit.clone());
561→
562→        if let Some(ref tx) = state.connect_tx {
563→            if let Err(e) = tx.try_send(ConnectRequest {
564→                node_id,
565→                permit: device_info.permit.clone(),
566→            }) {
567→                warn!(node_id = %node_id, error = %e, "Failed to send connect request");
568→            }
569→        }
570→
571→        Self::emit_event(state, CourierEvent::ConnectRequested {
572→            node_id: node_id.to_string(),
573→            permit: device_info.permit,
574→        });
575→    }
576→
577→    /// Find peer actor for a user by DID
578→    fn get_peer_actor_for_user<'a>(
579→        &self,
580→        user_did: &str,
581→        state: &'a CoordinatorState<C>,
582→    ) -> Option<&'a ActorRef<PeerMessage>> {
583→        state.authenticated_peers()
584→            .find(|(_, entry)| entry.auth.as_ref().map(|a| a.did.as_str()) == Some(user_did))
585→            .map(|(_, entry)| &entry.actor)
586→    }
587→
588→    /// Distribute layer permits for a new dynamic layer (Node mode)
589→    ///
590→    /// **Context**: Scribe detected new dynamic layer, permits already created by layer_unit
591→    /// **We do**: Store each permit in butler, send LayerPermitMsg to each recipient's PeerActor
592→    #[instrument(skip_all, fields(page_id = %page_id, layer = %layer_name, permit_count = permits.len()))]
593→    async fn on_distribute_layer_permits(
594→        &self,
595→        page_id: &str,
596→        layer_name: &str,
597→        permits: &[(String, String)],
598→        state: &mut CoordinatorState<C>,
599→    ) {
600→        info!(
601→            "Distributing {} layer permits for page={} layer={}",
602→            permits.len(), page_id, layer_name
603→        );
604→
605→        for (recipient_did, permit_token) in permits {
606→            // Store layer permit in butler
607→            if let Err(e) = state.butler.permits().store_layer_permit(
608→                page_id,
609→                recipient_did,
610→                layer_name,
611→                permit_token,
612→            ) {
613→                warn!(
614→                    recipient = %recipient_did,
615→                    error = %e,
616→                    "Failed to store layer permit"
617→                );
618→                continue;
619→            }
620→
621→            // Find PeerActor for this recipient and send
622→            if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
623→                if let Err(e) = actor.cast(PeerMessage::SendLayerPermit {
624→                    page_id: page_id.to_string(),
625→                    layer_name: layer_name.to_string(),
626→                    permit: permit_token.clone(),
627→                }) {
628→                    warn!(
629→                        recipient = %recipient_did,
630→                        error = %e,
631→                        "Failed to send LayerPermit to PeerActor"
632→                    );
633→                } else {
634→                    info!(recipient = %recipient_did, "Sent LayerPermit to PeerActor");
635→                }
636→            } else {
637→                // Peer not connected — permit stored, will be sent on reconnect
638→                debug!(
639→                    recipient = %recipient_did,
640→                    "Peer not connected, layer permit stored for reconnect"
641→                );
642→            }
643→        }
644→    }
645→
646→    /// Distribute updated page permits after reissue (Node mode)
647→    ///
648→    /// **Context**: New app installed → page permits reissued with new layers
649→    /// **We do**: Store updated permits in butler, send PermitUpdate to each recipient
650→    #[instrument(skip_all, fields(page_id = %page_id, permit_count = permits.len()))]
651→    async fn on_distribute_page_permit_updates(
652→        &self,
653→        page_id: &str,
654→        permits: &[(String, String)],
655→        state: &mut CoordinatorState<C>,
656→    ) {
657→        info!(
658→            "Distributing {} page permit updates for page={}",
659→            permits.len(), page_id
660→        );
661→
662→        for (recipient_did, permit_token) in permits {
663→            // Store updated permit in butler
664→            if let Err(e) = state.butler.permits().store_page_permit(
665→                page_id,
666→                recipient_did,
667→                permit_token,
668→            ) {
669→                warn!(
670→                    recipient = %recipient_did,
671→                    error = %e,
672→                    "Failed to store updated page permit"
673→                );
674→                continue;
675→            }
676→
677→            // Find PeerActor for this recipient and send
678→            if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
679→                if let Err(e) = actor.cast(PeerMessage::SendPermitUpdate {
680→                    page_id: page_id.to_string(),
681→                    permit: permit_token.clone(),
682→                }) {
683→                    warn!(
684→                        recipient = %recipient_did,
685→                        error = %e,
686→                        "Failed to send PermitUpdate to PeerActor"
687→                    );
688→                } else {
689→                    info!(recipient = %recipient_did, "Sent PermitUpdate to PeerActor");
690→                }
691→            } else {
692→                // Peer not connected — permit stored, will be picked up on reconnect
693→                debug!(
694→                    recipient = %recipient_did,
695→                    "Peer not connected, updated page permit stored for reconnect"
696→                );
697→            }
698→        }
699→    }
700→
701→    /// Handle page opened - refresh subscriptions for all authenticated peers
702→    ///
703→    /// **Context**: App opened a page, subscriptions may not be established yet
704→    /// **We do**: Send RefreshSubscriptions to all authenticated PeerActors
705→    /// **Design**: Ensures subscription after page open (race condition fix)
706→    #[instrument(skip_all, fields(page_id = %page_id))]
707→    async fn on_page_opened(&self, page_id: &str, state: &mut CoordinatorState<C>) {
708→        let peer_count = state.authenticated_peers().count();
709→        if peer_count == 0 {
710→            debug!(page_id = %page_id, "No authenticated peers to refresh subscriptions for");
711→            return;
712→        }
713→
714→        info!(page_id = %page_id, peer_count = peer_count, "Page opened, refreshing subscriptions for authenticated peers");
715→
716→        for (node_id, entry) in state.authenticated_peers() {
717→            if let Err(e) = entry.actor.cast(PeerMessage::RefreshSubscriptions) {
718→                warn!(node_id = %node_id, error = %e, "Failed to send RefreshSubscriptions");
719→            }
720→        }
721→    }
722→}
723→

