//! Coordinator - Minimal peer lifecycle manager
//!
//! The Coordinator handles:
//! - Peer lifecycle (Connected/Disconnected events from transport)
//! - Spawning PeerActors on new connections
//! - Authentication state tracking
//! - Cross-peer operations (relay, broadcast datagrams)
//!
//! All protocol handling is done by PeerActor. App communicates directly with PeerActor
//! for operations like publishing, subscribing, etc.
//!
//! # Generic Transport
//!
//! The Coordinator is generic over `C: Connection` to support different transports:
//! - `Coordinator<IrohConnection>`: Production with NAT traversal
//! - `Coordinator<MockConnection>`: Unit tests with in-memory channels

mod state;

use std::marker::PhantomData;
use std::sync::Arc;

use ractor::{Actor, ActorProcessingErr, ActorRef, SupervisionEvent};
use tracing::{debug, error, info, warn, instrument};
use transport::{Connection, NodeId};

use tokio::sync::{mpsc, oneshot};

use crate::handle::CourierEvent;
use crate::peer_actor::{PeerActor, PeerActorArgs, PeerMessage};
use crate::state::PeerType;
use crate::trace::MessageTrace;
use butler::Butler;

pub use state::{CoordinatorState, PeerEntry, PeerInfo};

// Type aliases for production use
pub type IrohCoordinator = Coordinator<transport::IrohConnection>;
pub type IrohCoordinatorMessage = CoordinatorMessage<transport::IrohConnection>;

/// Request for CourierRunner to initiate a connection
#[derive(Debug, Clone)]
pub struct ConnectRequest {
    pub node_id: NodeId,
    pub permit: String,
}

/// Messages received by Coordinator
///
/// Generic over `C: Connection` to support different transport implementations.
#[derive(Debug)]
pub enum CoordinatorMessage<C: Connection> {

    /// New connection from transport
    Connected {
        node_id: NodeId,
        conn: C,
    },

    /// Connection disconnected
    Disconnected { node_id: NodeId },

    /// PeerActor completed handshake
    PeerAuthenticated {
        node_id: NodeId,
        peer_type: PeerType,
        did: String,
        username: String,
    },

    /// PeerActor failed
    PeerFailed { node_id: NodeId, reason: String },

    /// Connect to peer (fire-and-forget, result via CourierEvent)
    ///
    /// **Context**: App wants to connect to a peer
    /// **We do**: Store permit, mark as pending, request transport connection
    /// **Events emitted**: PeerAuthenticated on success, ConnectionFailed on failure
    Connect {
        node_id: NodeId,
        permit: String,
    },

    /// Get PeerActor reference for direct communication
    GetPeerActor {
        node_id: NodeId,
        response: oneshot::Sender<Option<ActorRef<PeerMessage>>>,
    },

    /// Relay datagram to other peers (Node mode only)
    RelayDatagram {
        from_node_id: NodeId,
        data: Vec<u8>,
    },

    /// Broadcast datagram to all authenticated peers
    BroadcastDatagram { data: Vec<u8> },

    /// Scribe requested sync with a user
    EnsureSync { user_did: String },

    /// Distribute layer permits for a new dynamic layer (Node mode)
    ///
    /// **Context**: Scribe detected a new dynamic layer, permits already created
    /// **We do**: Store permits in butler, send LayerPermitMsg to each recipient's PeerActor
    DistributeLayerPermits {
        page_id: String,
        layer_name: String,
        permits: Vec<(String, String)>,  // (recipient_did, layer_permit_token)
    },

    /// Distribute updated page permits to peers (Node mode)
    ///
    /// **Context**: New app installed → page permits reissued with new layers
    /// **We do**: Store updated permits in butler, send PermitUpdate to each recipient's PeerActor
    DistributePagePermitUpdates {
        page_id: String,
        permits: Vec<(String, String)>,  // (recipient_did, new_permit_token)
    },

    /// Page opened - trigger subscription refresh for all authenticated peers
    ///
    /// **Context**: App opened a page, we need to ensure subscriptions are set up
    /// **We do**: Send RefreshSubscriptions to all authenticated PeerActors
    PageOpened { page_id: String },

    /// Check if a node is authenticated
    ///
    /// **Context**: Script/app wants to wait for auth before publishing
    /// **Returns**: true if handshake complete, false otherwise
    IsNodeAuthenticated {
        node_id: NodeId,
        response: oneshot::Sender<bool>,
    },

    /// Shutdown all actors
    Shutdown,
}

/// Courier mode (User or Node)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CourierMode {
    /// Running as user's device (connects TO node)
    User,
    /// Running as always-on node (accepts connections)
    Node,
}

/// Coordinator manages all PeerActors
///
/// Generic over `C: Connection` to support different transport implementations.
pub struct Coordinator<C: Connection> {
    _phantom: PhantomData<C>,
}

impl<C: Connection> Coordinator<C> {
    pub fn new() -> Self {
        Self { _phantom: PhantomData }
    }

    /// Emit an event to the app layer via event_tx channel
    fn emit_event(state: &CoordinatorState<C>, event: CourierEvent) {
        if let Some(tx) = &state.event_tx {
            if let Err(e) = tx.try_send(event) {
                warn!("Failed to emit event: {}", e);
            }
        }
    }

    /// Process a ConnectionEvent and convert to CoordinatorMessage
    ///
    /// **Note**: Transport now only emits lifecycle events (Connected/Disconnected).
    /// Message reading is done by PeerSession directly from the Connection.
    pub fn from_connection_event(event: transport::ConnectionEvent<C>) -> Option<CoordinatorMessage<C>> {
        match event {
            transport::ConnectionEvent::Connected { node_id, conn } => {
                Some(CoordinatorMessage::Connected { node_id, conn })
            }
            transport::ConnectionEvent::Disconnected { node_id } => {
                Some(CoordinatorMessage::Disconnected { node_id })
            }
        }
    }
}

impl<C: Connection> Default for Coordinator<C> {
    fn default() -> Self {
        Self::new()
    }
}

impl<C: Connection> Actor for Coordinator<C> {
    type Msg = CoordinatorMessage<C>;
    type State = CoordinatorState<C>;
    type Arguments = (
        NodeId,
        CourierMode,
        Arc<Butler>,
        crate::peer_actor::BlobStore,
        Option<mpsc::Sender<ConnectRequest>>,
        Option<mpsc::Sender<CourierEvent>>,
        Option<mpsc::UnboundedSender<MessageTrace>>,
    );

    #[instrument(skip_all)]
    async fn pre_start(
        &self,
        _myself: ActorRef<Self::Msg>,
        args: Self::Arguments,
    ) -> Result<Self::State, ActorProcessingErr> {
        let (our_node_id, mode, butler, blob_store, connect_tx, event_tx, message_tx) = args;

        info!("Coordinator started in {:?} mode (node_id={})", mode, our_node_id);

        Ok(CoordinatorState::new(
            our_node_id,
            mode,
            butler,
            blob_store,
            connect_tx,
            event_tx,
            message_tx,
        ))
    }

    async fn handle(
        &self,
        myself: ActorRef<Self::Msg>,
        message: Self::Msg,
        state: &mut Self::State,
    ) -> Result<(), ActorProcessingErr> {
        match message {

            CoordinatorMessage::Connected { node_id, conn } => {
                self.on_connected(myself.clone(), node_id, conn, state).await;
            }

            CoordinatorMessage::Disconnected { node_id } => {
                self.on_disconnected(node_id, state).await;
            }

            CoordinatorMessage::PeerAuthenticated {
                node_id,
                peer_type,
                did,
                username,
            } => {
                info!("Peer authenticated: {} ({}) - {:?}", username, node_id, peer_type);
                state.authenticate_peer(node_id, peer_type, did.clone(), username.clone());

                // Mark sovereign node as connected (for User mode connecting to their Node)
                if peer_type == PeerType::MyNode {
                    let node_id_str = node_id.to_string();
                    match state.butler.nodes().set_connected(&node_id_str, true) {
                        Ok(true) => info!("Marked sovereign node {} as connected", node_id_str),
                        Ok(false) => debug!("Sovereign node {} not found in storage", node_id_str),
                        Err(e) => warn!("Failed to mark sovereign node connected: {}", e),
                    }
                }

                // Emit event for app layer
                Self::emit_event(state, CourierEvent::PeerAuthenticated {
                    node_id: node_id.to_string(),
                    did,
                    username,
                });
            }

            CoordinatorMessage::PeerFailed { node_id, reason } => {
                warn!("Peer failed: {} - {}", node_id, reason);

                // Emit failure event for app layer
                Self::emit_event(state, CourierEvent::ConnectionFailed {
                    node_id: node_id.to_string(),
                    error: reason,
                });

                state.remove_peer(node_id);
            }

            CoordinatorMessage::Connect { node_id, permit } => {
                self.on_connect(node_id, permit, state).await;
            }

            CoordinatorMessage::GetPeerActor { node_id, response } => {
                let actor = state.get_actor(&node_id).cloned();
                let _ = response.send(actor);
            }

            CoordinatorMessage::RelayDatagram { from_node_id, data } => {
                if state.mode == CourierMode::Node {
                    for (peer_node_id, entry) in state.authenticated_peers() {
                        if peer_node_id != from_node_id {
                            if let Err(e) = entry.conn.send_datagram(&data) {
                                debug!(from = %from_node_id, to = %peer_node_id, error = %e, "Failed to relay datagram");
                            }
                        }
                    }
                }
            }

            CoordinatorMessage::BroadcastDatagram { data } => {
                for (node_id, entry) in state.authenticated_peers() {
                    if let Err(e) = entry.conn.send_datagram(&data) {
                        debug!(node_id = %node_id, error = %e, "Failed to send datagram");
                    }
                }
            }

            CoordinatorMessage::EnsureSync { user_did } => {
                self.on_ensure_sync(myself.clone(), user_did, state).await;
            }

            CoordinatorMessage::DistributeLayerPermits { page_id, layer_name, permits } => {
                self.on_distribute_layer_permits(&page_id, &layer_name, &permits, state).await;
            }

            CoordinatorMessage::DistributePagePermitUpdates { page_id, permits } => {
                self.on_distribute_page_permit_updates(&page_id, &permits, state).await;
            }

            CoordinatorMessage::PageOpened { page_id } => {
                self.on_page_opened(&page_id, state).await;
            }

            CoordinatorMessage::IsNodeAuthenticated { node_id, response } => {
                let is_auth = state.is_authenticated(&node_id);
                let _ = response.send(is_auth);
            }

            CoordinatorMessage::Shutdown => {
                info!("Coordinator shutting down");
                for (node_id, entry) in state.peers.drain() {
                    debug!("Stopping PeerActor {}", node_id);
                    entry.actor.stop(Some("coordinator shutdown".to_string()));
                }
                myself.stop(Some("shutdown".to_string()));
            }
        }

        Ok(())
    }

    async fn handle_supervisor_evt(
        &self,
        _myself: ActorRef<Self::Msg>,
        event: SupervisionEvent,
        state: &mut Self::State,
    ) -> Result<(), ActorProcessingErr> {
        match event {
            SupervisionEvent::ActorStarted(cell) => {
                debug!("Child actor started: {:?}", cell.get_id());
            }
            SupervisionEvent::ActorTerminated(cell, _, reason) => {
                debug!(
                    "Child actor {} terminated: {:?}",
                    cell.get_id(),
                    reason
                );
                // Find and remove from unified registry
                state.peers.retain(|node_id, entry| {
                    if entry.actor.get_id() == cell.get_id() {
                        debug!("Removing terminated PeerActor {}", node_id);
                        false
                    } else {
                        true
                    }
                });
            }
            SupervisionEvent::ActorFailed(cell, error) => {
                error!("Child actor {} failed: {}", cell.get_id(), error);
                // Same cleanup as terminated
                state.peers.retain(|node_id, entry| {
                    if entry.actor.get_id() == cell.get_id() {
                        debug!("Removing failed PeerActor {}", node_id);
                        false
                    } else {
                        true
                    }
                });
            }
            _ => {}
        }

        Ok(())
    }
}

impl<C: Connection> Coordinator<C> {
    /// Handle new connection - spawn PeerActor with permit if outbound
    #[instrument(skip_all, fields(node_id = %node_id))]
    async fn on_connected(
        &self,
        myself: ActorRef<CoordinatorMessage<C>>,
        node_id: NodeId,
        conn: C,
        state: &mut CoordinatorState<C>,
    ) {
        info!("New connection from: {}", node_id);

        // Check if this was an outbound connection WE initiated - get permit if so
        let is_outbound = state.pending_connections.remove(&node_id);
        let permit = if is_outbound {
            state.pending_permits.remove(&node_id)
        } else {
            None
        };

        if is_outbound && permit.is_none() {
            warn!("Outbound connection to {} but no permit - cannot handshake", node_id);
        }

        // Spawn PeerActor - if permit provided, it auto-initiates handshake
        let peer_actor = PeerActor::<C>::new(node_id);
        let args = PeerActorArgs {
            mode: state.mode,
            conn: conn.clone(),
            coordinator: myself.clone(),
            butler: state.butler.clone(),
            blob_store: state.blob_store.clone(),
            permit,
            message_tx: state.message_tx.clone(),
            our_node_id: state.our_node_id,
        };

        match Actor::spawn_linked(None, peer_actor, args, myself.get_cell()).await {
            Ok((actor_ref, _)) => {
                state.add_peer(node_id, actor_ref, conn);
                debug!("PeerActor spawned for {}", node_id);
            }
            Err(e) => {
                error!("Failed to spawn PeerActor for {}: {:?}", node_id, e);
            }
        }
    }

    /// Handle disconnection - cleanup peer state and emit event
    #[instrument(skip_all, fields(node_id = %node_id))]
    async fn on_disconnected(&self, node_id: NodeId, state: &mut CoordinatorState<C>) {
        info!("Disconnected: {}", node_id);

        if let Some(entry) = state.peers.remove(&node_id) {
            entry.actor.stop(Some("disconnected".to_string()));
        }

        state.pending_connections.remove(&node_id);
        state.pending_permits.remove(&node_id);

        // Emit disconnect event for app layer
        Self::emit_event(state, CourierEvent::PeerDisconnected {
            node_id: node_id.to_string(),
        });
    }

    /// Connect to peer (fire-and-forget, result via events)
    ///
    /// **Context**: App calls connect(), we store permit and mark as pending
    /// **Transport**: CourierRunner sees pending_connections and calls transport.connect()
    /// **Events**: PeerAuthenticated on success, ConnectionFailed on failure
    #[instrument(skip_all, fields(node_id = %node_id))]
    async fn on_connect(
        &self,
        node_id: NodeId,
        permit: String,
        state: &mut CoordinatorState<C>,
    ) {
        info!("Connect: node={}", node_id);

        // Check if already authenticated - emit event immediately
        if state.is_authenticated(&node_id) {
            info!("Peer {} already authenticated", node_id);
            if let Some(auth) = state.get_auth(&node_id) {
                Self::emit_event(state, CourierEvent::PeerAuthenticated {
                    node_id: node_id.to_string(),
                    did: auth.did.clone(),
                    username: auth.username.clone(),
                });
            }
            return;
        }

        // Check if already connected - initiate handshake with existing PeerActor
        if let Some(actor) = state.get_actor(&node_id).cloned() {
            info!("Peer {} already connected - initiating handshake", node_id);
            if let Err(e) = actor.cast(PeerMessage::InitiateHandshake { permit }) {
                warn!("Failed to send InitiateHandshake to {}: {:?}", node_id, e);
            }
            return;
        }

        // Mark as pending outbound connection and store permit
        state.pending_connections.insert(node_id);
        state.pending_permits.insert(node_id, permit.clone());

        // Request transport connection via CourierRunner
        if let Some(ref tx) = state.connect_tx {
            if let Err(e) = tx.try_send(ConnectRequest { node_id, permit }) {
                warn!(node_id = %node_id, error = %e, "Failed to send connect request");
                Self::emit_event(state, CourierEvent::ConnectionFailed {
                    node_id: node_id.to_string(),
                    error: format!("Failed to initiate connection: {}", e),
                });
            }
        }
    }

    /// Handle EnsureSync from Scribe - connect to user if not already connected
    #[instrument(skip_all, fields(user_did = %user_did))]
    async fn on_ensure_sync(
        &self,
        _myself: ActorRef<CoordinatorMessage<C>>,
        user_did: String,
        state: &mut CoordinatorState<C>,
    ) {
        info!(user_did = %user_did, "Scribe requested sync with user");

        // Check if user is already connected
        if let Some(peer_actor) = self.get_peer_actor_for_user(&user_did, state) {
            info!(user_did = %user_did, "User already connected, sending RefreshSubscriptions to PeerActor");
            let _ = peer_actor.cast(PeerMessage::RefreshSubscriptions);
            return;
        }

        // Resolve user_did to device info
        let device_info = match state.butler.contacts().resolve_device(&user_did) {
            Ok(Some(info)) => info,
            Ok(None) => {
                // In Node mode, viewers initiate connections - we don't reconnect to them
                // This is expected behavior, not a warning condition
                if state.mode == CourierMode::Node {
                    debug!(user_did = %user_did, "Viewer not connected (will reconnect when online)");
                } else {
                    warn!(user_did = %user_did, "No device info found for user");
                }
                return;
            }
            Err(e) => {
                warn!(user_did = %user_did, error = %e, "Failed to resolve device");
                return;
            }
        };

        let node_id = match device_info.node_id.parse::<NodeId>() {
            Ok(id) => id,
            Err(e) => {
                warn!(node_id = %device_info.node_id, error = ?e, "Failed to parse node_id");
                return;
            }
        };

        // Check if already connecting/connected
        if state.is_connected(&node_id) || state.pending_connections.contains(&node_id) {
            debug!(user_did = %user_did, node_id = %node_id, "Already connected/connecting");
            return;
        }

        info!(user_did = %user_did, node_id = %node_id, "Requesting connection for sync");

        state.pending_connections.insert(node_id);
        state.pending_permits.insert(node_id, device_info.permit.clone());

        if let Some(ref tx) = state.connect_tx {
            if let Err(e) = tx.try_send(ConnectRequest {
                node_id,
                permit: device_info.permit.clone(),
            }) {
                warn!(node_id = %node_id, error = %e, "Failed to send connect request");
            }
        }

        Self::emit_event(state, CourierEvent::ConnectRequested {
            node_id: node_id.to_string(),
            permit: device_info.permit,
        });
    }

    /// Find peer actor for a user by DID
    fn get_peer_actor_for_user<'a>(
        &self,
        user_did: &str,
        state: &'a CoordinatorState<C>,
    ) -> Option<&'a ActorRef<PeerMessage>> {
        state.authenticated_peers()
            .find(|(_, entry)| entry.auth.as_ref().map(|a| a.did.as_str()) == Some(user_did))
            .map(|(_, entry)| &entry.actor)
    }

    /// Distribute layer permits for a new dynamic layer (Node mode)
    ///
    /// **Context**: Scribe detected new dynamic layer, permits already created by layer_unit
    /// **We do**: Store each permit in butler, send LayerPermitMsg to each recipient's PeerActor
    #[instrument(skip_all, fields(page_id = %page_id, layer = %layer_name, permit_count = permits.len()))]
    async fn on_distribute_layer_permits(
        &self,
        page_id: &str,
        layer_name: &str,
        permits: &[(String, String)],
        state: &mut CoordinatorState<C>,
    ) {
        info!(
            "Distributing {} layer permits for page={} layer={}",
            permits.len(), page_id, layer_name
        );

        for (recipient_did, permit_token) in permits {
            // Store layer permit in butler
            if let Err(e) = state.butler.permits().store_layer_permit(
                page_id,
                recipient_did,
                layer_name,
                permit_token,
            ) {
                warn!(
                    recipient = %recipient_did,
                    error = %e,
                    "Failed to store layer permit"
                );
                continue;
            }

            // Find PeerActor for this recipient and send
            if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
                if let Err(e) = actor.cast(PeerMessage::SendLayerPermit {
                    page_id: page_id.to_string(),
                    layer_name: layer_name.to_string(),
                    permit: permit_token.clone(),
                }) {
                    warn!(
                        recipient = %recipient_did,
                        error = %e,
                        "Failed to send LayerPermit to PeerActor"
                    );
                } else {
                    info!(recipient = %recipient_did, "Sent LayerPermit to PeerActor");
                }
            } else {
                // Peer not connected — permit stored, will be sent on reconnect
                debug!(
                    recipient = %recipient_did,
                    "Peer not connected, layer permit stored for reconnect"
                );
            }
        }
    }

    /// Distribute updated page permits after reissue (Node mode)
    ///
    /// **Context**: New app installed → page permits reissued with new layers
    /// **We do**: Store updated permits in butler, send PermitUpdate to each recipient
    #[instrument(skip_all, fields(page_id = %page_id, permit_count = permits.len()))]
    async fn on_distribute_page_permit_updates(
        &self,
        page_id: &str,
        permits: &[(String, String)],
        state: &mut CoordinatorState<C>,
    ) {
        info!(
            "Distributing {} page permit updates for page={}",
            permits.len(), page_id
        );

        for (recipient_did, permit_token) in permits {
            // Store updated permit in butler
            if let Err(e) = state.butler.permits().store_page_permit(
                page_id,
                recipient_did,
                permit_token,
            ) {
                warn!(
                    recipient = %recipient_did,
                    error = %e,
                    "Failed to store updated page permit"
                );
                continue;
            }

            // Find PeerActor for this recipient and send
            if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
                if let Err(e) = actor.cast(PeerMessage::SendPermitUpdate {
                    page_id: page_id.to_string(),
                    permit: permit_token.clone(),
                }) {
                    warn!(
                        recipient = %recipient_did,
                        error = %e,
                        "Failed to send PermitUpdate to PeerActor"
                    );
                } else {
                    info!(recipient = %recipient_did, "Sent PermitUpdate to PeerActor");
                }
            } else {
                // Peer not connected — permit stored, will be picked up on reconnect
                debug!(
                    recipient = %recipient_did,
                    "Peer not connected, updated page permit stored for reconnect"
                );
            }
        }
    }

    /// Handle page opened - refresh subscriptions for all authenticated peers
    ///
    /// **Context**: App opened a page, subscriptions may not be established yet
    /// **We do**: Send RefreshSubscriptions to all authenticated PeerActors
    /// **Design**: Ensures subscription after page open (race condition fix)
    #[instrument(skip_all, fields(page_id = %page_id))]
    async fn on_page_opened(&self, page_id: &str, state: &mut CoordinatorState<C>) {
        let peer_count = state.authenticated_peers().count();
        if peer_count == 0 {
            debug!(page_id = %page_id, "No authenticated peers to refresh subscriptions for");
            return;
        }

        info!(page_id = %page_id, peer_count = peer_count, "Page opened, refreshing subscriptions for authenticated peers");

        for (node_id, entry) in state.authenticated_peers() {
            if let Err(e) = entry.actor.cast(PeerMessage::RefreshSubscriptions) {
                warn!(node_id = %node_id, error = %e, "Failed to send RefreshSubscriptions");
            }
        }
    }
}

//! Coordinator state management and helpers
//!
//! Provides unified state management for peer connections in a single registry.
//!
//! Generic over `C: Connection` to support different transport implementations.

use std::collections::{HashMap, HashSet};
use std::sync::Arc;

use ractor::ActorRef;
use tokio::sync::mpsc;
use tracing::warn;
use transport::{Connection, NodeId};

use crate::handle::CourierEvent;
use crate::peer_actor::{BlobStore, PeerMessage};
use crate::state::PeerType;
use crate::trace::MessageTrace;
use crate::ConnectRequest;
use butler::Butler;

use super::CourierMode;

/// Information about an authenticated peer
#[derive(Debug, Clone)]
pub struct PeerInfo {
    pub node_id: NodeId,
    pub peer_type: PeerType,
    pub did: String,
    pub username: String,
}

/// Unified peer entry - combines actor, connection, and auth state
///
/// Generic over `C: Connection` to support different transport implementations.
pub struct PeerEntry<C: Connection> {
    /// Reference to the PeerActor handling this connection
    pub actor: ActorRef<PeerMessage>,
    /// Connection handle for sending messages
    pub conn: C,
    /// None until authenticated, Some after successful handshake
    pub auth: Option<PeerInfo>,
}

/// Coordinator state with unified peer registry
///
/// Generic over `C: Connection` to support different transport implementations.
pub struct CoordinatorState<C: Connection> {
    /// Our node ID
    pub our_node_id: NodeId,

    /// Running mode (shell or node)
    pub mode: CourierMode,

    /// Butler reference for storage/crypto
    pub butler: Arc<Butler>,

    /// Blob store for assets
    pub blob_store: BlobStore,

    /// All connected peers (unified registry)
    pub peers: HashMap<NodeId, PeerEntry<C>>,

    /// Outbound connections we initiated (waiting for handshake)
    pub pending_connections: HashSet<NodeId>,

    /// Permits for pending outbound connections
    pub pending_permits: HashMap<NodeId, String>,

    /// Event subscribers
    pub event_tx: Option<mpsc::Sender<CourierEvent>>,

    /// Channel to request connections (handled by CourierRunner)
    pub connect_tx: Option<mpsc::Sender<ConnectRequest>>,

    /// Optional trace channel for protocol message capture (tests only)
    pub message_tx: Option<mpsc::UnboundedSender<MessageTrace>>,
}

impl<C: Connection> CoordinatorState<C> {
    /// Create new coordinator state
    pub fn new(
        our_node_id: NodeId,
        mode: CourierMode,
        butler: Arc<Butler>,
        blob_store: BlobStore,
        connect_tx: Option<mpsc::Sender<ConnectRequest>>,
        event_tx: Option<mpsc::Sender<CourierEvent>>,
        message_tx: Option<mpsc::UnboundedSender<MessageTrace>>,
    ) -> Self {
        Self {
            our_node_id,
            mode,
            butler,
            blob_store,
            peers: HashMap::new(),
            pending_connections: HashSet::new(),
            pending_permits: HashMap::new(),
            event_tx,
            connect_tx,
            message_tx,
        }
    }

    // Peer Lifecycle

    /// Add a new peer (on connection, before authentication)
    pub fn add_peer(&mut self, node_id: NodeId, actor: ActorRef<PeerMessage>, conn: C) {
        self.peers.insert(node_id, PeerEntry {
            actor,
            conn,
            auth: None,
        });
    }

    /// Mark peer as authenticated
    pub fn authenticate_peer(
        &mut self,
        node_id: NodeId,
        peer_type: PeerType,
        did: String,
        username: String,
    ) -> bool {
        if let Some(entry) = self.peers.get_mut(&node_id) {
            entry.auth = Some(PeerInfo {
                node_id,
                peer_type,
                did,
                username,
            });
            true
        } else {
            false
        }
    }

    /// Remove peer and all associated state (cleanup on disconnect)
    pub fn remove_peer(&mut self, node_id: NodeId) {
        self.peers.remove(&node_id);
        self.pending_connections.remove(&node_id);
        self.pending_permits.remove(&node_id);
    }

    // Peer Accessors

    /// Get peer actor if exists
    pub fn get_actor(&self, node_id: &NodeId) -> Option<&ActorRef<PeerMessage>> {
        self.peers.get(node_id).map(|e| &e.actor)
    }

    /// Get connection handle if exists
    pub fn get_conn(&self, node_id: &NodeId) -> Option<&C> {
        self.peers.get(node_id).map(|e| &e.conn)
    }

    /// Get peer info if authenticated
    pub fn get_auth(&self, node_id: &NodeId) -> Option<&PeerInfo> {
        self.peers.get(node_id)?.auth.as_ref()
    }

    /// Get full peer entry
    pub fn get_peer(&self, node_id: &NodeId) -> Option<&PeerEntry<C>> {
        self.peers.get(node_id)
    }

    // Auth Guards

    /// Require authenticated peer, returns None with warning if not
    pub fn require_auth(&self, node_id: NodeId, action: &str) -> Option<&PeerInfo> {
        match self.get_auth(&node_id) {
            Some(info) => Some(info),
            None => {
                warn!("Cannot {} for unauthenticated peer: {}", action, node_id);
                None
            }
        }
    }

    // Iterators

    /// Iterate over authenticated peers
    pub fn authenticated_peers(&self) -> impl Iterator<Item = (NodeId, &PeerEntry<C>)> {
        self.peers.iter()
            .filter(|(_, e)| e.auth.is_some())
            .map(|(id, e)| (*id, e))
    }

    /// Get all peer node IDs
    pub fn peer_node_ids(&self) -> Vec<NodeId> {
        self.peers.keys().copied().collect()
    }

    // State Queries

    /// Check if peer is connected (may or may not be authenticated)
    pub fn is_connected(&self, node_id: &NodeId) -> bool {
        self.peers.contains_key(node_id)
    }

    /// Check if peer is authenticated
    pub fn is_authenticated(&self, node_id: &NodeId) -> bool {
        self.get_auth(node_id).is_some()
    }

    // Scribe Integration (for ScribeConnect pattern)

    /// Get PeerActor by user DID
    ///
    /// **Context**: Used by Scribe to send ScribeConnect to the appropriate PeerActor
    /// **Returns**: PeerActor ref if user is authenticated, None otherwise
    pub fn get_peer_actor_for_did(&self, user_did: &str) -> Option<&ActorRef<PeerMessage>> {
        self.authenticated_peers()
            .find(|(_, entry)| entry.auth.as_ref().map(|a| a.did.as_str()) == Some(user_did))
            .map(|(_, entry)| &entry.actor)
    }

    /// Get the node's PeerActor (for User mode connecting to their node)
    ///
    /// **Context**: In User mode, Scribe needs to connect to the node's PeerActor
    /// **Returns**: PeerActor ref for the node if connected, None otherwise
    pub fn get_node_peer_actor(&self) -> Option<&ActorRef<PeerMessage>> {
        self.authenticated_peers()
            .find(|(_, entry)| entry.auth.as_ref().map(|a| a.peer_type) == Some(PeerType::MyNode))
            .map(|(_, entry)| &entry.actor)
    }

    /// Get all authenticated PeerActor refs for pages with shares
    ///
    /// **Context**: In Node mode, Scribe needs to connect to all PeerActors for peers with shares
    /// **Returns**: Iterator over (DID, PeerActor ref) for authenticated peers
    pub fn get_all_authenticated_peer_actors(&self) -> impl Iterator<Item = (&str, &ActorRef<PeerMessage>)> {
        self.authenticated_peers()
            .filter_map(|(_, entry)| {
                entry.auth.as_ref().map(|a| (a.did.as_str(), &entry.actor))
            })
    }
}

//! PeerActor - One actor per P2P connection
//!
//! Handles:
//! - Handshake state machine (Hello/Welcome/PermitGrant/Ack)
//! - Protocol message routing
//! - Per-peer state tracking
//!
//! # Handshake Flow (First Connection)
//!
//! ```text
//! Owner (User mode)                    Node (Node mode)
//!     │                                      │
//!     │──── Hello (first_connection) ───────>│
//!     │                                      │ validate permit
//!     │                                      │ store OwnerInfo
//!     │                                      │ issue permit_for_owner
//!     │<──────────── Welcome ────────────────│
//!     │ validate permit                      │
//!     │ store permit                         │
//!     │ issue permit_for_node                │
//!     │──────────── PermitGrant ────────────>│
//!     │                                      │ store permit
//!     │<──────────── Ack ────────────────────│
//!     │                                      │
//!   [Authenticated]                    [Authenticated]
//! ```

mod guards;
mod handshake;
mod publish;
mod sync;
mod consent;
mod assets;

use std::marker::PhantomData;
use std::sync::Arc;
use std::time::Instant;

use logging_utils::short;
use ractor::{Actor, ActorProcessingErr, ActorRef};
use tokio::io::AsyncReadExt;
use tracing::{debug, error, info, warn, instrument};
use transport::{BiStream, Connection, NodeId};

use crate::coordinator::{CoordinatorMessage, CourierMode};
use crate::message::*;
use crate::state::{PeerState, PeerType};
use crate::trace::{MessageTrace, TraceDirection};
use butler::{Butler, BroadcastPayload, ScribeMessage};

/// Messages received by PeerActor
#[derive(Debug)]
pub enum PeerMessage {
    /// Protocol message from Coordinator (already deserialized)
    Protocol(Message),

    /// Internal: Initiate handshake by sending Hello (User mode)
    InitiateHandshake {
        permit: String,
    },

    /// Internal: Publish a space to this peer (User mode)
    PublishSpace {
        space_id: String,
    },

    /// Internal: Publish a page to this peer (User mode)
    PublishPage {
        page_id: String,
    },

    /// Internal: Request shareable link for a space (User mode)
    ///
    /// **Context**: Owner wants to share a space with a viewer.
    /// **We do**: Send GetShareableLinkRequest to node, wait for response.
    GetShareableLink {
        space_id: String,
        response_tx: tokio::sync::oneshot::Sender<Result<String, String>>,
    },

    /// Internal: Request space content as viewer (User mode)
    ///
    /// **Context**: Viewer has aud:* permit from shareable link.
    /// **We do**: Send SpaceRequest to node with permit.
    RequestSpace {
        space_id: String,
        viewer_permit: String,
    },

    /// Internal: Subscribe to a page's Scribe for live updates
    ///
    /// **Context**: After handshake, we want live updates for pages we have access to
    /// **We do**: Subscribe to Scribe, spawn broadcast listener task
    SubscribeToPage {
        page_id: String,
        permit: String,
    },

    /// Internal: Broadcast payload received from Scribe
    ///

    ///
    /// **Context**: Scribe sent us an update to forward to peer
    /// **We do**: Encrypt and send as SyncOffer
    BroadcastReceived(BroadcastPayload),

    /// Internal: Issue sync consent permits and send to node (User/Viewer mode)
    ///
    /// **Context**: Viewer received space + pages, now issues consent permits
    /// **We do**: Issue consent permits via gurkha, send SyncConsentGrant to node
    IssueSyncConsent {
        space_id: String,
        space_template: String,
        page_template: String,
    },

    /// Internal: Refresh subscriptions to active Scribes
    ///
    /// **Context**: Page opened after connection established
    /// **We do**: Re-run subscribe_to_active_scribes to pick up new pages
    RefreshSubscriptions,

    /// Raw datagram received from peer (ephemeral data)
    ///
    /// **Context**: PeerActor owns the datagram read loop
    /// **We do**: Deserialize, route to Scribe via page_subscriptions
    Datagram {
        data: Vec<u8>,
    },

    /// Internal: Send a layer permit to this peer (Node mode)
    ///
    /// **Context**: Coordinator received NewDynamicLayer event with ready permits
    /// **We do**: Send LayerPermitMsg to peer
    SendLayerPermit {
        page_id: String,
        layer_name: String,
        permit: String,
    },

    /// Internal: Send updated page permit to this peer (Node mode)
    ///
    /// **Context**: Page permit reissued with new app layers
    /// **We do**: Send PermitUpdate message to peer
    SendPermitUpdate {
        page_id: String,
        permit: String,
    },

    /// Internal: Request an asset from the peer
    ///
    /// **Context**: External component (e.g., Coordinator) wants to fetch an asset
    /// **We do**: Send AssetPrepare message to peer
    RequestAsset {
        page_id: String,
        hash: String,
    },

    /// Scribe initiates connection to receive messages
    ///
    /// **Context**: Scribe spawned and wants to receive ephemeral/sync messages
    /// **We do**: Store connection, flush any buffered messages for this page
    /// **Design**: Receiver-initiates pattern ensures no lost messages
    ScribeConnect {
        page_id: String,
        scribe: ractor::ActorRef<butler::ScribeMessage>,
    },
}

/// Blob store abstraction - either real transport or mock for testing
#[derive(Clone)]
pub enum BlobStore {
    /// Real iroh-blobs via Transport
    Real(Arc<transport::Transport>),
    /// Mock blob store for testing (shared HashMap)
    Mock(Arc<transport::MockBlobStore>),
}

impl BlobStore {
    /// Add blob to store, returns iroh hash bytes
    pub async fn add_blob(&self, data: &[u8]) -> Result<[u8; 32], String> {
        match self {
            BlobStore::Real(transport) => {
                transport.add_blob(data).await
                    .map(|h| *h.as_bytes())
                    .map_err(|e| format!("Blob store error: {}", e))
            }
            BlobStore::Mock(mock) => Ok(mock.add_blob(data)),
        }
    }

    /// Download blob from peer, returns plaintext bytes
    pub async fn download_blob(&self, iroh_hash: &[u8; 32], node_id: NodeId) -> Result<Vec<u8>, String> {
        match self {
            BlobStore::Real(transport) => {
                let hash = transport::BlobHash::from_bytes(*iroh_hash);
                transport.download_blob(hash, node_id).await
                    .map_err(|e| format!("Download failed: {}", e))
            }
            BlobStore::Mock(mock) => {
                mock.download_blob(iroh_hash)
                    .ok_or_else(|| "Blob not found in mock store".to_string())
            }
        }
    }
}

/// Arguments for spawning PeerActor
