    pub device_id: String,

//! Scribe message types
//!
//! Contains both the actor messages (ScribeMessage) and shared types
//! (BroadcastPayload, PageUpdate, etc.)

use std::collections::HashMap;
use std::path::PathBuf;

use ractor::RpcReplyPort;
use tokio::sync::mpsc;
use serde::{Serialize, Deserialize};

use domains::{QuerySpec, QueryDelta, QueryResult, JsonOp};
use crate::Result;

/// Payload sent to PeerActor for broadcast (3-step sync protocol)
///
/// **Context**: Scribe sends this to PeerActor, who then sends SyncOffer to peer
/// **state_vector**: Our state vector after this update (for 3-step protocol)
/// **layer_type**: Protocol routing hint (App=snapshot, Data=incremental, Static=blob)
#[derive(Debug, Clone)]
pub struct BroadcastPayload {
    pub page_id: String,
    pub layer_name: String,
    pub update: Vec<u8>,
    /// Our state vector for this layer (for SyncOffer message)
    pub state_vector: Vec<u8>,
    /// Layer type for protocol routing
    pub layer_type: domains::LayerType,
}

/// Ephemeral broadcast payload (generic)
///
/// **Context**: Scribe sends this to Butler/Courier for datagram broadcast
/// **Transport**: Unreliable QUIC datagram (fire-and-forget, lowest latency)
/// **Design**: Generic payload - app defines format; protocol routes by page_id
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct EphemeralBroadcast {
    /// Page ID for routing
    pub page_id: String,
    /// Opaque payload - app defines format (JSON with type/x/y, etc.)
    pub payload: Vec<u8>,
}

/// Outbound ephemeral data (Scribe → PeerActor via channel)
///
/// **Context**: Same pattern as BroadcastPayload for CRDT data
/// **Flow**: Scribe broadcasts ephemeral to all subscriber channels,
///           PeerActor listener receives and sends datagram to peer
#[derive(Debug, Clone)]
pub struct EphemeralOutbound {
    /// Page ID for routing (used in datagram)
    pub page_id: String,
    /// Opaque payload - app defines format (JSON with type/x/y, etc.)
    pub payload: Vec<u8>,
}

/// Delta operations for different Loro container types
///
/// **Context**: Represents incremental changes to CRDT containers
/// **Usage**: Lua apps can apply deltas for efficient UI updates (preserve scroll, animations)
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type")]
pub enum LoroDelta {
    /// List delta: sequence of Retain/Insert/Delete operations
    List { ops: Vec<ListOp> },

    /// Map delta: updated keys
    Map { updated: HashMap<String, Option<serde_json::Value>> },

    /// Text delta (for future rich text support)
    Text { ops: Vec<TextOp> },
}

/// List delta operations (applied sequentially)
///
/// **Context**: Represents changes to a Loro list container
/// **Example**: [Retain(3), Insert([msg4]), Delete(1)] means "skip 3 items, insert msg4, delete 1 item"
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "op")]
pub enum ListOp {
    /// Keep N items unchanged (advance cursor)
    Retain { count: usize },

    /// Insert values at current position
    Insert { values: Vec<serde_json::Value> },

    /// Delete N items at current position
    Delete { count: usize },
}

/// Text delta operations (for rich text editing)
///
/// **Context**: Represents changes to a Loro text container
/// **Note**: Deferred for now - will implement when we need rich text editing
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "op")]
pub enum TextOp {
    /// Keep N characters unchanged
    Retain { count: usize },

    /// Insert text at current position
    Insert { text: String },

    /// Delete N characters at current position
    Delete { count: usize },
}

// Unified Page Update Channel (Replaces PageEvent + EphemeralEvent + QueryDelta)

/// Unified update enum for all page events
///
/// **Context**: Single channel replaces 3 separate broadcast types
/// **Benefits**: 3 listener tasks → 1, unified fan-out logic
/// **Consumers**: UI/Lua callbacks, Broadcast to peers, Derivation engine
#[derive(Debug, Clone)]
pub enum PageUpdate {
    /// Layer data changed (local edit or remote sync)
    LayerChanged {
        layer: String,
        from_peer: Option<(String, String)>,  // (did, device_id)
        /// Structured operations extracted from the update (same format as validation)
        /// Enables surgical UI updates - Lua can process individual ops
        ops: Option<Vec<JsonOp>>,
        delta: Option<LoroDelta>,
        state_vector: Vec<u8>,
        /// Full layer state as JSON — None when delta is available (avoids O(N) serialization)
        /// Some for initial load, wildcard bindings, or fallback scenarios
        full_data: Option<serde_json::Value>,
        /// True if this is a newly created layer (first time seeing it)
        created: bool,
    },

    /// Ephemeral data from remote peer (cursor, typing, etc.)
    Ephemeral {
        user_did: String,
        device_id: String,
        payload: Vec<u8>,
    },

    /// Query result changed
    QueryUpdated {
        query_id: String,
        delta: QueryDelta,
    },

    /// Peer subscribed to this page
    PeerSubscribed {
        did: String,
        /// Username if presence.share_username is true in their permit
        username: Option<String>,
    },

    /// Peer unsubscribed from this page
    PeerUnsubscribed {
        did: String,
    },

    /// Structured ephemeral received (permission-validated)
    ///
    /// **Context**: Ephemeral with func name, validated against permit
    StructuredEphemeral {
        from_did: String,
        func: String,
        args: serde_json::Value,
    },
}

/// Type alias for unified page update channel
pub type PageUpdateTx = mpsc::Sender<PageUpdate>;

/// Events emitted for sync coordination (consumed by Coordinator)
///
/// **Context**: Scribe emits these when it needs to sync with a user.
/// NOTE: Scribe only knows user_did. Coordinator handles everything else:
/// - Device resolution
/// - Connection establishment
/// - Subscription (PeerActor discovers active Scribes on connect)
#[derive(Debug, Clone)]
pub enum SyncEvent {
    /// Ensure this user is synced (connected + subscribed to active Scribes)
    EnsureSync { user_did: String },

    /// Node detected a new dynamic layer — permits already created by layer_unit
    ///
    /// **Context**: Scribe detected a dynamic layer (via schema match) and used
    /// PermitIssuer to create ready-to-send permits. Coordinator just distributes.
    NewDynamicLayer {
        page_id: String,
        layer_name: String,
        /// Ready-to-send permits: (recipient_did, layer_permit_token)
        permits: Vec<(String, String)>,
    },

    /// Layer access changed — new permits need distribution
    ///
    /// **Context**: Scribe added a participant and issued permits for connected peers
    LayerAccessChanged {
        page_id: String,
        layer_name: String,
        /// Ready-to-send permits: (recipient_did, layer_permit_token)
        permits: Vec<(String, String)>,
    },
}

// ScribeMessage - Actor Messages for Scribe

/// Messages received by Scribe actor
#[derive(Debug)]
pub enum ScribeMessage {
    /// Peer subscription - PeerActor subscribes to receive layer updates
    ///
    /// **Context**: PeerActor connects for a page and wants sync updates
    /// **We do**: Parse permit, extract layer permissions + sync policies, store subscriber
    Subscribe {
        user_did: String,
        device_id: String,
        /// Callback to send CRDT broadcasts to this peer
        broadcast_tx: mpsc::Sender<BroadcastPayload>,
        /// Callback to send ephemeral broadcasts to this peer (cursor, typing)
        /// PeerActor creates this channel, spawns listener that sends datagrams
        ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
        /// Raw permit string - we parse to extract permissions
        permit: String,
    },

    /// Peer unsubscription
    Unsubscribe {
        user_did: String,
        device_id: String,
    },

    /// Apply layer update (from local UI or remote peer)
    ///
    /// **Context**: Local edit or remote sync push
    /// **We do**: Permission check, CRDT merge, broadcast to subscribers
    ApplyUpdate {
        layer_name: String,
        update: Vec<u8>,
        /// None = local edit, Some = remote peer
        from_peer: Option<(String, String)>,
        /// Permit from SyncOffer (for peers not yet subscribed)
        permit: Option<String>,
    },

    /// Apply layer update with result feedback (for SyncAccept control)
    ///
    /// **Context**: Remote sync push that needs success/failure feedback
    /// **We do**: Permission check, CRDT merge, broadcast to subscribers, reply with result
    ApplyUpdateWithResult {
        layer_name: String,
        update: Vec<u8>,
        from_peer: Option<(String, String)>,
        permit: Option<String>,
        reply: tokio::sync::oneshot::Sender<std::result::Result<(), String>>,
    },

    /// Sync request - peer wants updates since their version
    SyncRequest {
        layer_name: String,
        their_vector: Vec<u8>,
        reply: RpcReplyPort<Result<Vec<u8>>>,
    },

    /// Export full snapshot (for initial sync or send_full_snapshot policy)
    ExportSnapshot {
        layer_name: String,
        reply: RpcReplyPort<Result<Vec<u8>>>,
    },

    /// Get our state vector (for incremental sync)
    GetStateVector {
        layer_name: String,
        reply: RpcReplyPort<Result<Vec<u8>>>,
    },

    /// Get updates since a given state vector (for resync after divergence)
    ///
    /// **Context**: SyncAccept showed divergence, sender needs full diff
    /// **We do**: Export updates from our LoroDoc since their vector
    GetUpdatesSince {
        layer_name: String,
        state_vector: Vec<u8>,
        reply: tokio::sync::oneshot::Sender<Result<Vec<u8>>>,
    },

    /// Replace layer entirely with snapshot (for SyncReset recovery)
    ///
    /// **Context**: User mode received SyncSnapshot after max resyncs exceeded
    /// **We do**: Replace local layer with authoritative snapshot from node
    /// **Invariant**: Node is source of truth for divergence resolution
    ReplaceLayer {
        layer_name: String,
        snapshot: Vec<u8>,
        reply: tokio::sync::oneshot::Sender<std::result::Result<(), String>>,
    },

    /// Flush dirty layers to storage
    Flush,

    /// Update peer's cached state vector (from PeerActor after SyncAccept/SyncAck)
    ///
    /// **Context**: PeerActor received confirmation of peer's state
    /// **We do**: Update in-memory vector cache (persistence via periodic flush)
    UpdatePeerVector {
        user_did: String,
        device_id: String,
        layer_name: String,
        state_vector: Vec<u8>,
    },

    /// Periodic reconciliation - check all subscribers for divergence
    ///
    /// **Context**: Timer fires every 30 seconds
    /// **We do**: Compare vectors, re-broadcast if diverged
    ReconcileWithPeers,

    /// Ensure a list layer exists (creates if needed)
    ///
    /// **Context**: Lua calls loro:list("name") - ensures layer exists
    /// **We do**: Create layer if needed, reply with success
    /// **Why**: Lua doesn't hold direct LoroList handle (stale after ReplaceLayer)
    EnsureLoroList {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<()>>,
    },

    /// Ensure a map layer exists (creates if needed)
    ///
    /// **Context**: Lua calls loro:map("name") - ensures layer exists
    /// **We do**: Create layer if needed, reply with success
    /// **Why**: Lua doesn't hold direct LoroMap handle (stale after ReplaceLayer)
    EnsureLoroMap {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<()>>,
    },

    /// Check if a layer exists (for get_list/get_map that return nil if missing)
    ///
    /// **Context**: Lua calls loro:get_list("name") - returns nil if missing
    LayerExists {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<bool>,
    },

    // Typed read operations (Lua → Scribe, avoids stale handles)

    /// Get item at index from a list layer
    ///
    /// **Context**: Lua calls list:get(index)
    /// **We do**: Read from current LoroDoc (never stale)
    ListGet {
        layer_name: String,
        index: usize,
        reply: tokio::sync::oneshot::Sender<Result<Option<serde_json::Value>>>,
    },

    /// Get list length
    ///
    /// **Context**: Lua calls list:length()
    ListLength {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<usize>>,
    },

    /// Get value by key from a map layer
    ///
    /// **Context**: Lua calls map:get(key)
    MapGet {
        layer_name: String,
        key: String,
        reply: tokio::sync::oneshot::Sender<Result<Option<serde_json::Value>>>,
    },

    /// Get map length
    ///
    /// **Context**: Lua calls map:length()
    MapLength {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<usize>>,
    },

    /// Get all keys from a map
    ///
    /// **Context**: Lua calls map:keys()
    MapKeys {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<Vec<String>>>,
    },

    /// List layers matching a pattern
    ///
    /// **Context**: Lua calls loro:list_layers("*:order")
    /// **We do**: Return layer names matching glob pattern
    ListLayers {
        pattern: String,
        reply: tokio::sync::oneshot::Sender<Vec<String>>,
    },

    /// Subscribe to all page updates (unified channel)
    ///
    /// **Context**: App runtime subscribes to receive ALL page updates
    /// **We do**: Store sender, forward PageUpdate events when they occur
    /// **Consumers**: UI/Lua callbacks, Broadcast to peers, Derivation engine - all filter as needed
    /// **Design**: Unified channel for layer changes, ephemeral data, and peer presence
    SubscribeToPageUpdates {
        tx: mpsc::Sender<PageUpdate>,
    },


    /// Get layer data as JSON value
    ///
    /// **Context**: Lua bindings need to read layer content
    /// **We do**: Export layer as serde_json::Value
    GetLayerData {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<serde_json::Value>>,
    },

    /// Get current snapshot for a layer (for testing/debugging)
    ///
    /// **Context**: Test wants to verify Scribe state without waiting for persistence
    /// **We do**: Export current snapshot and return via reply channel
    GetSnapshot {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Option<Vec<u8>>>,
    },

    /// Get layer data as JSON (for egui rendering)
    ///
    /// **Context**: egui window wants to read Loro data directly
    /// **We do**: Export layer content as JSON value
    GetLayerJson {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Option<serde_json::Value>>,
    },

    /// Get all layers as JSON context (for egui rendering)
    ///
    /// **Context**: egui window wants full context for CEL evaluation
    /// **We do**: Export all layer contents as a single JSON object
    GetContext {
        reply: tokio::sync::oneshot::Sender<serde_json::Value>,
    },

    /// Execute a query and return results
    ///
    /// **Context**: HUML renderer needs filtered/sorted/paginated data
    /// **We do**: Execute query against layer, apply filter/sort/limit, return results
    Query {
        spec: QuerySpec,
        reply: tokio::sync::oneshot::Sender<Result<QueryResult>>,
    },

    /// Subscribe to query updates
    ///
    /// **Context**: HUML renderer wants incremental updates when query results change
    /// **We do**: Store subscription, send QueryDelta when underlying data changes
    SubscribeQuery {
        spec: QuerySpec,
        /// Channel to send deltas when results change
        delta_tx: mpsc::Sender<QueryDelta>,
    },

    /// Unsubscribe from query updates
    UnsubscribeQuery {
        query_id: String,
    },

    /// Update layer from JSON (for UI commits via CEL commit())
    ///
    /// **Context**: HUML renderer's CEL `commit()` returns JSON values to persist.
    /// **We do**: Update the layer at the given path, notify query subscribers.
    UpdateFromJson {
        layer_name: String,
        path: String,
        value: serde_json::Value,
        /// Optional reply for error handling
        reply: Option<tokio::sync::oneshot::Sender<Result<()>>>,
    },

    // Typed CRDT Operations (from template actions)

    /// Push item to a list (append)
    ///
    /// **Context**: Template `action: { messages: append({...}) }`
    /// **We do**: Layer.list_push, broadcast, notify subscribers
    ListPush {
        layer_name: String,
        path: String,
        item: serde_json::Value,
    },

    /// Insert item at index in a list
    ListInsert {
        layer_name: String,
        path: String,
        index: usize,
        item: serde_json::Value,
    },

    /// Delete item at index from a list
    ListDelete {
        layer_name: String,
        path: String,
        index: usize,
    },

    /// Insert/update key in a map
    ///
    /// **Context**: Template `action: { users: set("id", {...}) }`
    MapInsert {
        layer_name: String,
        path: String,
        key: String,
        value: serde_json::Value,
    },

    /// Delete key from a map
    MapDelete {
        layer_name: String,
        path: String,
        key: String,
    },

    /// Increment/decrement a counter
    ///
    /// **Context**: Template `action: { likes: increment(1) }`
    CounterInc {
        layer_name: String,
        path: String,
        amount: i64,
    },

    /// Create a dynamic layer (from Lua app)
    ///
    /// **Context**: Lua calls scribe:create_layer("channels/general/messages")
    /// **We do**: Validate schema exists in permit, generate path with our DID, create layer
    /// **We reply**: Full layer name (with page_id and DID prefix)
    CreateDynamicLayer {
        /// Schema key from dynamic_layer_schemas, e.g. "channels/{id}/messages"
        schema_key: String,
        /// User-chosen ID that fills the {id} in the schema, e.g. "general"
        layer_id: String,
        reply: tokio::sync::oneshot::Sender<std::result::Result<String, String>>,
    },

    /// Add a DID as participant to an explicit dynamic layer
    ///
    /// **Context**: Lua calls scribe:add_layer_access(layer_name, did)
    /// **We do**: Check manage_layer_access capability, store participant, issue permit if subscribed
    AddLayerAccess {
        layer_name: String,
        did: String,
        reply: tokio::sync::oneshot::Sender<std::result::Result<(), String>>,
    },

    /// Remove a DID from an explicit dynamic layer
    ///
    /// **Context**: Lua calls scribe:remove_layer_access(layer_name, did)
    /// **We do**: Check manage_layer_access capability, remove participant
    RemoveLayerAccess {
        layer_name: String,
        did: String,
        reply: tokio::sync::oneshot::Sender<std::result::Result<(), String>>,
    },

    /// Authorize a subscriber DID for a specific layer
    ///
    /// **Context**: Viewer received LayerPermit from node. Authorize the node
    /// (subscriber) on the local Scribe's LayerUnit so the observer broadcasts to it.
    AuthorizeLayerSubscriber {
        layer_name: String,
        subscriber_did: String,
    },

    /// Shutdown the actor
    Shutdown,

    // Ephemeral Events (from datagrams via PeerActor)

    /// Remote ephemeral data (from datagram via PeerActor)
    ///
    /// **Context**: Peer sent ephemeral data (cursor, typing, etc.) for this page
    /// **We do**: Forward to subscribed apps AND relay to other peers via ephemeral channels
    /// **Note**: Not persisted in CRDT - purely ephemeral
    /// **Design**: Protocol layer routes opaque bytes; app layer defines meaning
    RemoteEphemeral {
        /// Who sent this (from peer state, may be None if not authenticated)
        user_did: Option<String>,
        /// Device/connection ID of sender (for relay exclusion)
        device_id: Option<String>,
        /// Opaque payload - app defines format (JSON with type/x/y, etc.)
        payload: Vec<u8>,
    },

    /// Send ephemeral data to peers (from Lua)
    ///
    /// **Context**: Local user wants to broadcast ephemeral data (cursor, typing, etc.)
    /// **We do**: Forward via ephemeral broadcast channel to Courier
    /// **Design**: App layer provides opaque payload; protocol layer routes by page_id
    SendEphemeral {
        /// Opaque payload - app defines format (JSON with type/x/y, etc.)
        payload: Vec<u8>,
    },

    /// Send structured ephemeral with func name (permission-validated)
    ///
    /// **Context**: Local user wants to broadcast structured ephemeral (typing, cursor, etc.)
    /// **We do**: Validate func against our permit's ephemeral_funcs, then broadcast
    /// **Design**: Structured format allows permission control per-function
    SendStructuredEphemeral {
        /// Function name (validated against permit.ephemeral_funcs)
        func: String,
        /// Arguments (arbitrary JSON)
        args: serde_json::Value,
    },

    /// Remote structured ephemeral received (needs validation)
    ///
    /// **Context**: Peer sent structured ephemeral via datagram
    /// **We do**: Validate func against sender's permit, then emit to app subscribers
    RemoteStructuredEphemeral {
        /// Sender's DID
        from_did: String,
        /// Sender's device ID
        device_id: String,
        /// Function name (validated against sender's permit)
        func: String,
        /// Arguments
        args: serde_json::Value,
    },

    // Derivation Operations (via ScribeLuaRuntime)

    /// Rebuild a derived layer from all source layers
    ///
    /// **Context**: Called on startup or manual rebuild request
    /// **We do**: Clear derived layer, transform ALL entries from ALL matching sources
    RebuildDerived {
        target: String,
        reply: tokio::sync::oneshot::Sender<std::result::Result<usize, String>>,
    },

    /// Rebuild all derived layers (on startup)
    RebuildAllDerived {
        reply: tokio::sync::oneshot::Sender<std::result::Result<(), String>>,
    },

    /// Check if derivation is enabled on this Scribe
    ///
    /// **Context**: Lua bindings check before registering rules
    IsDerivationEnabled {
        reply: tokio::sync::oneshot::Sender<bool>,
    },

    /// Create an empty derived layer
    ///
    /// **Context**: When registering a derivation rule, create target layer
    CreateDerivedLayer {
        target_layer: String,
    },

    // App Refresh Operations

    /// Refresh app from filesystem (owner only)
    ///
    /// **Context**: Owner wants to reload app code from disk (development workflow)
    /// **We do**: Read files from app_dir, update app layer, commit (triggers broadcast)
    /// **Consumers**: UI Reload button, Debug socket command
    RefreshApp {
        app_name: String,
        app_dir: PathBuf,
        reply: tokio::sync::oneshot::Sender<std::result::Result<Vec<String>, String>>,
    },

    /// Get app files from in-memory layer
    ///
    /// **Context**: App restart needs current files from Scribe's in-memory layer
    /// **We do**: Extract files from app layer and return
    /// **Why**: Storage may be stale; Scribe has the latest synced content
    GetAppFiles {
        app_name: String,
        reply: tokio::sync::oneshot::Sender<std::result::Result<HashMap<String, String>, String>>,
    },

    /// Get subscriber count (for Lua peers:count() binding)
    ///
    /// **Context**: Node script wants to check if anyone is listening before broadcasting
    /// **We do**: Return count of current subscribers
    GetSubscriberCount {
        reply: tokio::sync::oneshot::Sender<usize>,
    },
}

//! Scribe actor state and configuration types
//!
//! Contains all state structs, type aliases, and configuration for the Scribe actor.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, RwLock};

use tokio::sync::mpsc;

use domains::{Layer, QuerySpec, QueryResult, QueryDelta};

use crate::layer_unit::LayerUnit;
use crate::{
    BroadcastPayload, EphemeralOutbound, PageUpdate, SyncEvent,
    LayerStorageRef, PeerVectorStorageRef, PeerResolverRef, PermitIssuerRef,
};

// Layer Name Normalization

/// Normalize a layer name by stripping `{page_id}/` prefix if present
///
/// **Context**: Lua apps and wire protocol use prefixed names (`{page_id}/messages`)
/// but Scribe stores layers with bare names (`messages`). This strips the prefix
/// at the Scribe boundary so all internal lookups use consistent bare names.
pub fn normalize_layer_name(name: &str, page_id: &str) -> String {
    let prefix = format!("{}/", page_id);
    if let Some(bare) = name.strip_prefix(&prefix) {
        bare.to_string()
    } else {
        name.to_string()
    }
}

// Sync Configuration

/// Sync mode derived from permit capabilities
///
/// **Design**: Capability-based, not role-based
/// - Mode is derived from permit's sync configuration
/// - No hardcoded role names in decision logic
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SyncMode {
    /// Sync to a specific source node (users sync to their node)
    ToSource,
    /// Broadcast to all authorized peers (node mode)
    Broadcast,
}

impl Default for SyncMode {
    fn default() -> Self {
        SyncMode::Broadcast
    }
}

/// Sync configuration derived from permit
///
/// **Context**: Determines how this Scribe syncs based on permit capabilities
/// - ToSource: Sync to a specific source node (owner/viewer/customer)
/// - Broadcast: Broadcast to all authorized peers (node)
#[derive(Debug, Clone)]
pub struct SyncConfig {
    /// Sync mode derived from permit (capability-based)
    pub mode: SyncMode,
    /// For ToSource: node_id to sync to
    /// For Broadcast: None (uses list_authorized_users callback)
    pub sync_target: Option<String>,
}

// Subscriber Types

/// Information about a subscribed peer
///
/// **Design**: Stores the parsed permit directly instead of extracted fields.
/// All access checks delegate to gurkha::Permit methods, ensuring consistency.
pub struct SubscriberInfo {
    /// Parsed page permit for all access checks (static layers)
    /// Stores the full permit so we can use its methods directly
    pub permit: gurkha::Permit,
    /// Subscriber's DID (for pattern expansion with {aud})
    /// Extracted from permit audience and normalized to DID format

    /// Extracted from permit audience and normalized to DID format
    pub subscriber_did: String,
    /// Whether this subscriber is visible (from permit presence config)
    /// Visible peers have their entry written to the presence layer
    pub is_visible: bool,
    /// Whether this subscriber can see others' presence
    /// Gates whether the presence layer is synced to this peer
    pub can_see_others: bool,
    /// Display name for this subscriber (from permit presence config)
    pub display_name: Option<String>,
    /// Channel to send CRDT broadcasts
    pub broadcast_tx: mpsc::Sender<BroadcastPayload>,
    /// Channel to send ephemeral broadcasts (cursor, typing)
    /// PeerActor creates this, spawns listener that sends datagrams
    pub ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
    /// Their last known state vectors (layer_name → version_vector)
    pub vectors: HashMap<String, Vec<u8>>,
}

impl SubscriberInfo {
    /// Check if subscriber can receive updates for layer (two-tier)
    ///
    /// **Context**: Used at subscribe time to populate LayerUnit.authorized_dids
    /// **Two-tier**: Checks page permit (static layers) then layer permits (dynamic layers)
    pub fn can_receive_layer(&self, layer_name: &str, page_id: &str) -> bool {
        // Block presence layer for peers who can't see others
        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !self.can_see_others {
            return false;
        }
        // Check if layer is in no_incoming_updates (sync facts)
        if self.permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
            return false;
        }
        // Check page permit only (layer permits are now handled via LayerUnit.authorized_dids)
        self.permit.can_read_layer(layer_name, page_id, &self.subscriber_did)
    }

    /// Check if subscriber can write to layer
    ///
    /// **Context**: Used during incoming update validation
    /// **Note**: Write auth stays subscriber-centric for now. For dynamic layer writes,
    /// the node trusts sync_target (path 2 in Permissions::can_write).
    pub fn can_write_layer(&self, layer_name: &str, page_id: &str) -> bool {
        self.permit.can_write_layer(layer_name, page_id, &self.subscriber_did)
    }
}

/// Query subscription info
pub struct QuerySubscriberInfo {
    /// Query specification
    pub spec: QuerySpec,
    /// Channel to send deltas
    pub delta_tx: mpsc::Sender<QueryDelta>,
    /// Current version (monotonically increasing)
    pub version: u64,
    /// Last known result (for computing deltas)
    pub last_result: Option<QueryResult>,
}

// Actor State

/// Scribe actor state
pub struct ScribeState {
    /// Page identifier
    pub page_id: String,
    /// Per-layer compute units (layer_name → LayerUnit)
    pub units: HashMap<String, LayerUnit>,
    /// Peer subscribers (user_did, device_id) → SubscriberInfo
    /// Arc<RwLock> allows Loro observer callback to send directly to peers
    pub subscribers: Arc<RwLock<HashMap<(String, String), SubscriberInfo>>>,
    /// Query subscribers (query_id → QuerySubscriberInfo)
    pub query_subscribers: HashMap<String, QuerySubscriberInfo>,

    /// Layer persistence (saves layer snapshots)
    pub layer_storage: LayerStorageRef,
    /// Peer vector persistence (saves/loads peer state vectors)
    pub vector_storage: PeerVectorStorageRef,
    /// Peer resolver (node mode only) - lists authorized users, loads permits
    pub peer_resolver: Option<PeerResolverRef>,
    /// Permit issuer (node mode only) - issues layer permits for dynamic layers
    pub permit_issuer: Option<PermitIssuerRef>,

    /// Sync configuration derived from permit (mode + sync_target)
    pub sync_config: Option<SyncConfig>,
    /// Channel to emit sync events (EnsureSync) - consumed by Coordinator
    pub sync_event_tx: Option<mpsc::Sender<SyncEvent>>,

    /// Unified page update channel - all events flow through here
    /// **Consumers**: UI/Lua callbacks, Broadcast to peers, Derivation engine
    /// **Design**: Single channel for layer changes, ephemeral data, peer presence
    /// **Arc<RwLock>**: Shared with observer tasks so new subscribers are visible
    pub page_update_subscribers: Arc<RwLock<Vec<mpsc::Sender<PageUpdate>>>>,

    /// Pending update source for observer context
    /// **Context**: Set before import() so observer knows who caused the change
    /// **Usage**: Observer reads this to populate `from_peer` in PageEvent
    /// **Cleared**: After import() completes
    pub pending_update_source: Arc<Mutex<Option<(String, String)>>>,

    // Note: ephemeral events now go through page_update_subscribers (PageUpdate::Ephemeral)
    // outbound ephemeral goes directly via SubscriberInfo.ephemeral_tx (Scribe → PeerActor channels)

    /// Validation handle (for kunki node mode validation)
    /// If provided, Scribe delegates validation to external ValidationService
    /// This enables validation.lua to access presence_lib from LuaRuntime
    /// Falls back to local validation if not available (though we're removing ScribeLuaRuntime)
    pub validation_handle: Option<crate::validation_handle::ValidationHandle>,

    /// Parsed permit - provides should_sync_layer, can_write_layer etc.
    /// Uses gurkha::Permit directly with page_id/did passed to methods
    pub our_permit: Option<gurkha::Permit>,
    /// Our DID (for pattern expansion with {aud})
    pub our_did: String,

    /// Shutdown sender for node script tick loop (if running)
    /// **Context**: Set when is_node=true and entry_node found in manifest
    /// **Usage**: Send () to shutdown the tick loop
    pub node_script_shutdown: Option<mpsc::Sender<()>>,

    /// Pending layer authorizations for layers that don't exist yet
    /// **Context**: AuthorizeLayerSubscriber received before create_layer_from_peer
    /// **Usage**: Applied when the layer is created
    pub pending_layer_authorizations: HashMap<String, Vec<String>>,
}

/// Arguments for spawning Scribe
pub struct ScribeArgs {
    pub page_id: String,
    pub layers: HashMap<String, Layer>,

    /// Layer persistence (saves layer snapshots)
    pub layer_storage: LayerStorageRef,
    /// Peer vector persistence (saves/loads peer state vectors)
    pub vector_storage: PeerVectorStorageRef,
    /// Peer resolver (node mode only) - lists authorized users, loads permits
    pub peer_resolver: Option<PeerResolverRef>,
    /// Permit issuer (node mode only) - issues layer permits for dynamic layers
    pub permit_issuer: Option<PermitIssuerRef>,

    /// Optional: Sync configuration derived from permit (relationship + sync_target)
    /// - Owner: sync to sovereign node
    /// - Node: broadcast only (no outbound sync)
    /// - Viewer: sync to source node
    pub sync_config: Option<SyncConfig>,
    /// Channel to emit sync events (EnsureSync) - consumed by Coordinator
    pub sync_event_tx: Option<mpsc::Sender<SyncEvent>>,
    /// Validation handle (for kunki node mode validation)
    /// If provided, Scribe delegates validation to external ValidationService
    pub validation_handle: Option<crate::validation_handle::ValidationHandle>,
    /// Our permit for this page (local write authorization)
    /// Used to check if we can write to a layer before committing
    pub our_permit: Option<String>,
    /// Our DID (for pattern expansion and validation)
    pub our_did: String,
    /// Our username (for node script permit bindings)
    pub our_username: String,
    /// Whether this Scribe runs on a node (enables derivation engine and node scripts)
    pub is_node: bool,
    // Note: ephemeral_broadcast_tx removed - outbound ephemeral now goes directly via
    // SubscriberInfo.ephemeral_tx (Scribe → PeerActor channels)
}

impl ScribeState {
    /// Check if a layer should sync based on permit configuration
    ///
    /// **Context**: Used to filter out local-only layers (sync: false) before broadcasting
    /// **Returns**: true if layer should sync, false if local-only
    pub fn should_sync_layer(&self, layer_name: &str) -> bool {
        self.our_permit
            .as_ref()
            .map(|permit| permit.should_sync_layer(layer_name, &self.page_id, &self.our_did))
            .unwrap_or(true)  // No permit means sync everything
    }

    /// Check if we can write to a layer
    pub fn can_write_layer(&self, layer_name: &str) -> bool {
        self.our_permit
            .as_ref()
            .map(|permit| permit.can_write_layer(layer_name, &self.page_id, &self.our_did))
            .unwrap_or(true)  // No permit means full access
    }
}

