135→// Debug Capture Layer
136→
137→use tracing::{Event, Subscriber};
138→use tracing_subscriber::layer::Context;
139→use tracing_subscriber::Layer;
140→
141→/// A tracing layer that captures log events and sends them to a broadcast channel
142→///
143→/// This layer intercepts all log events and sends them as `DebugLogEntry` to
144→/// a tokio broadcast channel, allowing external consumers (like ai_interface)
145→/// to access protocol-level logs from all libs.
146→pub struct DebugCaptureLayer {
147→    tx: tokio::sync::broadcast::Sender<DebugLogEntry>,
148→    instance_name: Option<String>,
149→}
150→
151→impl DebugCaptureLayer {
152→    pub fn new(
153→        tx: tokio::sync::broadcast::Sender<DebugLogEntry>,
154→        instance_name: Option<String>,
155→    ) -> Self {
156→        Self { tx, instance_name }
157→    }
158→}
159→
160→impl<S> Layer<S> for DebugCaptureLayer
161→where
162→    S: Subscriber,
163→{
164→    fn on_event(&self, event: &Event<'_>, _ctx: Context<'_, S>) {
165→        let metadata = event.metadata();
166→        let level = metadata.level().to_string();
167→        let target = metadata.target().to_string();
168→
169→        // Extract message from event fields
170→        let mut msg = String::new();
171→        let mut visitor = MessageVisitor(&mut msg);
172→        event.record(&mut visitor);
173→
174→        let entry = DebugLogEntry {
175→            ts: chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string(),
176→            level,
177→            target,
178→            msg,
179→            instance: self.instance_name.clone(),
180→        };
181→
182→        // Send to channel - ignore errors (no receivers)
183→        let _ = self.tx.send(entry);
184→    }
185→}
