187→/// Visitor to extract message field from tracing events
188→struct MessageVisitor<'a>(&'a mut String);
189→
190→impl<'a> tracing::field::Visit for MessageVisitor<'a> {
191→    fn record_debug(&mut self, field: &tracing::field::Field, value: &dyn std::fmt::Debug) {
192→        if field.name() == "message" {
193→            *self.0 = format!("{:?}", value);
194→        } else if self.0.is_empty() {
195→            // Capture first field if no message
196→            self.0.push_str(&format!("{}={:?}", field.name(), value));
197→        } else {
198→            self.0.push_str(&format!(" {}={:?}", field.name(), value));
199→        }
200→    }
201→
202→    fn record_str(&mut self, field: &tracing::field::Field, value: &str) {
203→        if field.name() == "message" {
204→            *self.0 = value.to_string();
205→        } else if self.0.is_empty() {
206→            self.0.push_str(&format!("{}={}", field.name(), value));
207→        } else {
208→            self.0.push_str(&format!(" {}={}", field.name(), value));
209→        }
210→    }
211→}
