270→/// Initialize rich tracing with tree formatting
271→///
272→/// This sets up a hierarchical logging system with optional file output.
273→/// The tree format shows nested function calls with indentation, making it
274→/// easy to trace execution flow through async code and multiple services.
275→///
276→/// When `debug_tx` is provided in config, all logs are also sent to that
277→/// broadcast channel for external consumers (like ai_interface).
278→///
279→/// # Example Output
280→/// ```text
281→/// 🎯 handle_add_folder name="My Folder"
282→///   ├─📁 create_folder folder_id="f_abc123"
283→///   │ ├─🔐 issue_folder_owner_token
284→///   │ │ └─✓ 8.7ms
285→///   │ └─✓ 45.6ms
286→///   └─✓ 50.1ms
287→/// ```
288→pub fn init_rich_tracing(
289→    config: LogConfig,
290→) -> Result<Option<WorkerGuard>, Box<dyn std::error::Error>> {
291→    let mut guard = None;
292→
293→    // Create filter: use RUST_LOG level if set, otherwise config.level,
294→    // but ALWAYS apply our third-party noise suppressions
295→    let base_level = std::env::var("RUST_LOG").unwrap_or_else(|_| config.level.clone());
296→    let filter = EnvFilter::try_new(format!(
297→        "{},\
298→         hyper=warn,\
299→         hyper_util=warn,\
300→         rustls=error,\
301→         iroh=warn,\
302→         iroh::socket=off,\
303→         iroh::net_report=off,\
304→         iroh::net_report::report=off,\
305→         quinn=warn,\
306→         netlink_proto=error,\
307→         netlink_sys=error,\
308→         netlink_packet_route=off,\
309→         hickory_proto=error,\
310→         hickory_resolver=error,\
311→         hickory_client=error,\
312→         portmapper=off,\
313→         tokio_tungstenite=warn,\
314→         tungstenite=warn,\
315→         netwatch=warn,\
316→         iroh_quinn_proto::connection=warn,\
317→         iroh_relay=warn,\
318→         igd_next::aio::tokio=warn,\
319→         tantivy=warn,\
320→         reqwest=warn,\
321→         asset_protocol=warn,\
322→         loro_internal=off,\
323→         loro_internal::oplog=off,\
324→         loro_internal::oplog::change_store=off,\
325→         loro_internal::oplog::change_store::block_encode=off,\
326→         loro_kv_store=off,\
327→         wgpu_core=warn,\
328→         wgpu_hal=off,\
329→         wgpu_hal::gles=off,\
330→         winit=warn,\
331→         naga=warn",
332→        base_level
333→    ))?;
334→
335→    // Create optional debug capture layer (sends logs to broadcast channel)
336→    let debug_layer = config.debug_tx.map(|tx| {
337→        DebugCaptureLayer::new(tx, config.instance_name.clone())
338→    });
339→
340→    let registry = tracing_subscriber::registry().with(filter).with(debug_layer);
341→
342→    // JSON stdout mode (for ai_interface to parse)
343→    if config.log_to_stdout && config.stdout_json {
344→        let json_layer = fmt::Layer::new()
345→            .json()
346→            .with_ansi(false);
347→
