190→async fn handle_start(
191→    passphrase: &str,
192→    redb_store: Arc<RedbStore>,
193→    debug_socket: Option<String>,
194→    data_dir: &std::path::Path,
195→) -> Result<(), Box<dyn std::error::Error>> {
196→    // Check if user exists in Butler
197→    if !butler::is_signed_up(&redb_store)? {
198→        error!("No user found. Please run 'init' first.");
199→        return Ok(());
200→    }
201→
202→    info!("Loading identity...");
203→
204→    // Login with Butler (returns Herald Identity)
205→    let identity = butler::login(&redb_store, passphrase)?;
206→    let identity_data = butler::get_identity_data(&redb_store)?.ok_or("Identity data not found")?;
