211→    // Create Butler with LayerCache, AssetStore and set identity
212→    let layer_cache = Arc::new(RwLock::new(LayerCache::new(redb_store.clone(), 100)));
213→    let assets_path = data_dir.join("assets");
214→    let asset_store = Arc::new(butler::AssetStore::new(&assets_path).expect("Failed to create asset store"));
