216→    // Create sync event channel (Scribe → Coordinator)
217→    // Node mode DOES need EnsureSync - to trigger RefreshSubscriptions when pages are opened
218→    let (sync_tx, sync_rx) = tokio::sync::mpsc::channel::<butler::SyncEvent>(32);
