220→    // Create page opened channel for node runtime auto-start
221→    let (page_opened_tx, mut page_opened_rx) = tokio::sync::mpsc::channel::<String>(32);
222→
223→    let butler = Arc::new(Butler::new(redb_store.clone(), layer_cache, asset_store, Some(sync_tx)));
