227→    // Create node runtime manager for derivation
228→    let node_runtime = Arc::new(NodeRuntimeManager::new(butler.clone()));
229→
230→    // Spawn task to auto-start node runtime when pages are opened
231→    //
232→    // **Context**: App layers (containing init.lua, node.lua) arrive via SyncOffer
233→    // AFTER the page is opened. First attempt may fail because apps().list() is empty.
234→    // We retry a few times with delay to wait for app layers to sync.
235→    let node_runtime_for_task = node_runtime.clone();
236→    tokio::spawn(async move {
237→        while let Some(page_id) = page_opened_rx.recv().await {
238→            info!(page_id = %page_id, "Page opened, starting node runtime");
239→            let runtime = node_runtime_for_task.clone();
240→            let pid = page_id.clone();
241→            tokio::spawn(async move {
242→                for attempt in 0..10u32 {
243→                    match runtime.start_node_for_page(&pid).await {
244→                        Ok(()) => {
245→                            info!(page_id = %pid, attempt, "Node runtime started");
246→                            return;
247→                        }
248→                        Err(e) => {
249→                            if attempt < 9 {
250→                                debug!(page_id = %pid, attempt, error = %e, "Node runtime not ready, retrying");
251→                                tokio::time::sleep(std::time::Duration::from_secs(2)).await;
252→                            } else {
253→                                warn!(page_id = %pid, error = %e, "Failed to start node runtime after retries");
254→                            }
255→                        }
256→                    }
257→                }
258→            });
259→        }
260→    });
261→
262→
263→    // Initialize Transport layer using the device key from Butler
264→    info!("Initializing transport layer...");
265→    let device_key = butler.device_key().await
266→        .map_err(|e| format!("Failed to get device key: {:?}", e))?;
267→    let transport_config = TransportConfig::new(device_key);
268→    let (transport, event_rx) = Transport::init(transport_config)
269→        .await
270→        .map_err(|e| format!("Failed to init transport: {}", e))?;
271→
272→    let transport = Arc::new(transport);
273→    let node_id = transport.node_id();
274→
275→    info!("✔ Transport initialized");
276→    info!("✔ Node ID: {}", node_id);
277→
278→    // Get relay URLs
279→    let relay_urls = transport.relay_urls();
280→    if !relay_urls.is_empty() {
281→        info!("✔ Relay: {}", relay_urls[0]);
282→    }
283→
284→    // Start debug server if requested (keep reference for updating state later)
285→    let debug_server_arc: Option<Arc<KunkiControlServer>> = if let Some(ref socket_path) = debug_socket {
286→        let socket_path = PathBuf::from(socket_path);
287→        let debug_server = Arc::new(KunkiControlServer::new(socket_path.clone(), "kunki".to_string(), Some(butler.clone())));
288→
289→        // Set initial state (connection_string will be updated after generation)
290→        debug_server.set_state(NodeState {
291→            node_id: node_id.to_string(),
292→            did: identity.did().to_string(),
293→            username: identity_data.username.clone(),
294→            connected_peers: vec![],
295→            relay_url: relay_urls.first().cloned(),
296→            connection_string: None,
297→        }).await;
298→
299→        // Spawn debug server
300→        let server = debug_server.clone();
301→        tokio::spawn(async move {
302→            if let Err(e) = server.start().await {
303→                error!(error = %e, "Debug server error");
304→            }
305→        });
306→
307→        info!("✔ Debug server enabled on: {:?}", socket_path);
308→        Some(debug_server)
309→    } else {
310→        None
311→    };
312→
313→    // Create HandshakeServices with Butler
314→    let handshake_services = Arc::new(HandshakeServices::new(butler.clone()));
315→
316→    // Initialize Courier with services for auto-processing
317→    let (courier_handle, mut courier_events, courier) = Courier::init_with_services(
318→        CourierMode::Node,
319→        transport.clone(),
320→        Some(handshake_services),
321→    );
322→
323→    // Note: Router starts accepting connections automatically when Transport::init() is called
324→
325→    // Spawn Courier event processor
326→    tokio::spawn(async move {
327→        courier.run(event_rx).await;
328→    });
329→
330→    // Forward sync events to Coordinator (Scribe → Coordinator)
331→    // This enables EnsureSync to trigger RefreshSubscriptions for connected peers
332→    let handle_for_sync = courier_handle.clone();
333→    let mut sync_rx = sync_rx;
334→    tokio::spawn(async move {
335→        while let Some(event) = sync_rx.recv().await {
336→            match event {
337→                butler::SyncEvent::EnsureSync { user_did } => {
338→                    tracing::info!(user_did = %user_did, "Node received EnsureSync from Scribe, forwarding to Coordinator");
339→                    if let Err(e) = handle_for_sync.ensure_sync(&user_did) {
340→                        tracing::warn!(user_did = %user_did, error = %e, "Failed to forward EnsureSync");
341→                    } else {
342→                        tracing::info!(user_did = %user_did, "Node forwarded EnsureSync to Coordinator");
343→                    }
344→                }
345→                butler::SyncEvent::NewDynamicLayer { page_id, layer_name, permits } => {
346→                    tracing::info!(
347→                        page_id = %page_id,
348→                        layer = %layer_name,
349→                        permit_count = permits.len(),
350→                        "Node received NewDynamicLayer from Scribe"
351→                    );
352→                    if let Err(e) = handle_for_sync.distribute_layer_permits(&page_id, &layer_name, permits) {
353→                        tracing::warn!(error = %e, "Failed to distribute layer permits");
354→                    }
355→                }
356→                butler::SyncEvent::LayerAccessChanged { page_id, layer_name, permits } => {
357→                    tracing::info!(
358→                        page_id = %page_id,
359→                        layer = %layer_name,
360→                        permit_count = permits.len(),
361→                        "Node received LayerAccessChanged from Scribe"
362→                    );
363→                    if let Err(e) = handle_for_sync.distribute_layer_permits(&page_id, &layer_name, permits) {
364→                        tracing::warn!(error = %e, "Failed to distribute layer permits for access change");
365→                    }
366→                }
367→            }
368→        }
369→    });
370→
371→    // Note: Node scripts are now started automatically by Scribe when is_node=true
372→    // Scribe manages the node script lifecycle via node_script_shutdown handle
373→
374→    // Spawn application event handler (logging only)
375→    // Note: Node scripts are now started automatically by Scribe when is_node=true
376→    let _courier_handle = courier_handle.clone(); // Keep handle for future use
377→    tokio::spawn(async move {
378→        while let Some(event) = courier_events.recv().await {
379→            match event {
380→                CourierEvent::PeerAuthenticated {
381→                    node_id,
382→                    did,
