509→/// Setup profiling tools (tokio-console and/or tracing-flame)
510→///
511→/// **Modes** (based on environment variables):
512→/// - `FLAME_OUTPUT` + `TOKIO_CONSOLE_PORT` → both layers
513→/// - `FLAME_OUTPUT` only → flame layer only (no console overhead)
514→/// - `TOKIO_CONSOLE_PORT` only → console layer only
515→///
516→/// **Environment variables**:
517→/// - `TOKIO_CONSOLE_PORT`: Port for tokio-console (enables console layer)
518→/// - `FLAME_OUTPUT`: Path for flame graph output file (enables flame layer)
519→#[cfg(feature = "profiling")]
520→fn setup_profiling() -> Option<tracing_flame::FlushGuard<std::io::BufWriter<File>>> {
521→    use tracing_subscriber::prelude::*;
522→
523→    let console_port: Option<u16> = std::env::var("TOKIO_CONSOLE_PORT")
524→        .ok()
525→        .and_then(|p| p.parse().ok());
526→    let flame_path = std::env::var("FLAME_OUTPUT").ok();
527→
528→    match (&flame_path, console_port) {
529→        // Both flame + console
530→        (Some(path), Some(port)) => {
531→            let (flame_layer, guard) = match tracing_flame::FlameLayer::with_file(path) {
532→                Ok((layer, guard)) => (Some(layer), Some(guard)),
533→                Err(e) => {
534→                    eprintln!("Failed to create flame layer: {}", e);
535→                    (None, None)
536→                }
537→            };
538→
539→            let console_layer = console_subscriber::ConsoleLayer::builder()
540→                .server_addr(([127, 0, 0, 1], port))
541→                .spawn();
542→
543→            tracing_subscriber::registry()
544→                .with(console_layer)
545→                .with(flame_layer)
546→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
547→                .init();
548→
549→            tracing::info!(port = port, path = %path, "Profiling: tokio-console + flame");
550→            guard
551→        }
552→        // Flame only (no console overhead)
553→        // Filter out tokio runtime TRACE spans (normally consumed by console-subscriber)
554→        (Some(path), None) => {
555→            let (flame_layer, guard) = match tracing_flame::FlameLayer::with_file(path) {
556→                Ok((layer, guard)) => (Some(layer), Some(guard)),
557→                Err(e) => {
558→                    eprintln!("Failed to create flame layer: {}", e);
559→                    (None, None)
560→                }
561→            };
562→
563→            let filter = tracing_subscriber::EnvFilter::new(
564→                "info,tokio=off,runtime=off",
565→            );
566→
567→            tracing_subscriber::registry()
568→                .with(filter)
569→                .with(flame_layer)
570→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
571→                .init();
572→
573→            tracing::info!(path = %path, "Profiling: flame only (no console overhead)");
574→            guard
575→        }
576→        // Console only
577→        (None, Some(port)) => {
578→            let console_layer = console_subscriber::ConsoleLayer::builder()
579→                .server_addr(([127, 0, 0, 1], port))
580→                .spawn();
581→
582→            tracing_subscriber::registry()
583→                .with(console_layer)
584→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
585→                .init();
586→
587→            tracing::info!(port = port, "Profiling: tokio-console only");
588→            None
589→        }
590→        // Neither - just fmt logging
591→        (None, None) => {
592→            let filter = tracing_subscriber::EnvFilter::new(
593→                "info,tokio=off,runtime=off",
594→            );
595→
596→            tracing_subscriber::registry()
597→                .with(filter)
598→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
599→                .init();
600→
601→            tracing::info!("Profiling feature enabled but no FLAME_OUTPUT or TOKIO_CONSOLE_PORT set");
602→            None
603→        }
604→    }
605→}
