    // Serialize to capture broadcast if active
    if let Some(tx) = &state.capture_tx {
        if let Ok(json) = serde_json::to_string(&serde_json::json!({
            "type": "courier_event",
            "ts": chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string(),
